	template <class Fn>
	struct ScopeExit
	{
		Fn fn;
		bool active = true;

		explicit ScopeExit(Fn a_fn) :
			fn(a_fn)
		{}

		ScopeExit(const ScopeExit&) = delete;
		ScopeExit& operator=(const ScopeExit&) = delete;

		~ScopeExit()
		{
			if (active)
				fn();
		}

		void Release()
		{
			active = false;
		}
	};

	template <class Fn>
	ScopeExit(Fn) -> ScopeExit<Fn>;

