	const char* GetVRRenderScalePostMutationProgressPhaseName(
		VRVendorRelatchPolicy::PostMutationProgressPhase a_phase) noexcept
	{
		using Phase = VRVendorRelatchPolicy::PostMutationProgressPhase;
		switch (a_phase) {
		case Phase::None:
			return "none";
		case Phase::MutationEntered:
			return "mutation_entered";
		case Phase::TableChanged:
			return "table_changed";
		case Phase::EmergencyRecoveryRequested:
			return "emergency_recovery_requested";
		case Phase::RecoveryResourcesReady:
			return "recovery_resources_ready";
		case Phase::EmergencyCreatorClaimed:
			return "emergency_creator_claimed";
		case Phase::EngineTargetsReconciled:
			return "engine_targets_reconciled";
		case Phase::ContractPublished:
			return "contract_published";
		case Phase::PresentationStabilizing:
			return "presentation_stabilizing";
		default:
			return "unknown";
		}
	}

	uint64_t GetVRRenderScalePostMutationTerminalDeadlineMilliseconds(
		VRVendorRelatchPolicy::PostMutationProgressPhase a_phase) noexcept
	{
		return VRVendorRelatchPolicy::SelectPostMutationTerminalDeadline({
			.progressPhase = a_phase,
			.debuggerAttached = ::IsDebuggerPresent() != FALSE,
			.stalledDeadlineMs =
				kVRRenderScalePostMutationStalledDeadlineMilliseconds,
			.progressingDeadlineMs =
				kVRRenderScalePostMutationProgressingDeadlineMilliseconds,
			.debuggerDeadlineMs =
				kVRRenderScaleRecoverableDebuggerDeadlineMilliseconds,
		});
	}

	uint64_t GetVRRenderScaleRecoverableFallbackDeadlineMilliseconds() noexcept
	{
		return ::IsDebuggerPresent() != FALSE ?
		           kVRRenderScaleRecoverableDebuggerDeadlineMilliseconds :
		           kVRRenderScalePreMutationNativeFallbackAbsoluteDeadlineMilliseconds;
	}

	struct VRRenderScaleSystemCommitSample
	{
		bool valid = false;
		uint64_t usageBytes = 0;
		uint64_t limitBytes = 0;
		uint64_t headroomBytes = 0;
		double ratio = 0.0;
		bool processPrivateUsageValid = false;
		uint64_t processPrivateUsageBytes = 0;
	};

	VRRenderScaleSystemCommitSample QueryVRRenderScaleSystemCommit() noexcept
	{
		VRRenderScaleSystemCommitSample sample{};
		MEMORYSTATUSEX memoryStatus{};
		memoryStatus.dwLength = static_cast<DWORD>(sizeof(memoryStatus));
		if (::GlobalMemoryStatusEx(&memoryStatus) && memoryStatus.ullTotalPageFile != 0) {
			sample.valid = true;
			sample.limitBytes = memoryStatus.ullTotalPageFile;
			sample.headroomBytes = std::min<uint64_t>(memoryStatus.ullAvailPageFile, sample.limitBytes);
			sample.usageBytes = sample.limitBytes - sample.headroomBytes;
			sample.ratio = static_cast<double>(sample.usageBytes) / static_cast<double>(sample.limitBytes);
		}

		PROCESS_MEMORY_COUNTERS_EX processMemory{};
		processMemory.cb = static_cast<DWORD>(sizeof(processMemory));
		if (::GetProcessMemoryInfo(
				::GetCurrentProcess(),
				reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&processMemory),
				processMemory.cb)) {
			sample.processPrivateUsageValid = true;
			sample.processPrivateUsageBytes = processMemory.PrivateUsage;
		}
		return sample;
	}

	uint64_t GetVRRenderScaleSystemCommitReserve(uint64_t a_commitLimitBytes) noexcept
	{
		if (a_commitLimitBytes == 0)
			return 0;

		const uint64_t scaledReserve = a_commitLimitBytes / kVRRenderScaleSystemCommitReserveScaleDenominator;
		return std::min(
			a_commitLimitBytes,
			std::clamp(
				scaledReserve,
				kVRRenderScaleSystemCommitMinimumReserveBytes,
				kVRRenderScaleSystemCommitMaximumReserveBytes));
	}

	uint64_t GetVRRenderScaleSystemCommitAdmissionLimit(uint64_t a_commitLimitBytes) noexcept
	{
		return a_commitLimitBytes - GetVRRenderScaleSystemCommitReserve(a_commitLimitBytes);
	}

	uint64_t GetVRRenderScaleDoorHandoffSystemCommitAdmissionLimit(uint64_t a_commitLimitBytes) noexcept
	{
		return a_commitLimitBytes > kVRRenderScaleSystemCommitMinimumReserveBytes ?
		           a_commitLimitBytes - kVRRenderScaleSystemCommitMinimumReserveBytes :
		           0u;
	}

