	bool TryGetTexture2DDesc(ID3D11Resource* resource, D3D11_TEXTURE2D_DESC& outDesc)
	{
		if (!resource)
			return false;

		winrt::com_ptr<ID3D11Texture2D> texture;
		if (FAILED(resource->QueryInterface(IID_PPV_ARGS(texture.put()))))
			return false;

		texture->GetDesc(&outDesc);
		return true;
	}

	// Hot-Envelope: answer "where did the engine actually write pixels" from
	// logged data rather than from someone judging an image in a headset.
	//
	// Every conclusion this investigation has reached about eye placement came
	// from a human looking at stereo while something else moved underneath them,
	// and two of those readings later turned out to be confounded. This decides
	// it mechanically.
	//
	// Method: copy one scanline per frame into a staging texture and compare it
	// byte-for-byte with the previous frame's. Columns whose bytes change are
	// being rendered; columns that never change across the window are stale or
	// were never touched. That is exactly what separates the two candidates:
	//
	//   repacked           active [0, render)                     no gap
	//   allocation halves  active [0, renderHalf) and
	//                      [allocHalf, allocHalf + renderHalf)     gap between
	//
	// The gap either exists or it does not, which needs no judgement at all.
	//
	// Deliberately no format decoding: we ask only whether bytes changed, never
	// what colour they are, so this works for whatever format the target uses.
	// It also means ordinary head motion supplies all the variation needed.
	struct EnvelopeColumnProbe
	{
		static constexpr uint32_t kRingDepth = 3u;
		static constexpr uint32_t kProbeFrames = 48u;
		static constexpr uint32_t kMaxWidth = 16384u;
		// A column must change in at least this many sampled frames to count as
		// rendered. One change is not enough: a single spurious difference -
		// dither, a one-off clear, a resource alias - would mark a dead column
		// active and erase the very gap this exists to detect.
		static constexpr uint8_t kMinChanges = 3u;
		// Columns adjacent to a boundary are ambiguous, so only report a gap
		// wider than this. Well below the smallest real gap (274 px).
		static constexpr size_t kMinGapWidth = 32u;

		struct Slot
		{
			winrt::com_ptr<ID3D11Texture2D> staging[kRingDepth];
			std::vector<uint8_t> previous;
			std::vector<uint8_t> changes;
			// Spatial variation against the neighbouring pixel in the same
			// frame. This exists to falsify the probe's one load-bearing
			// assumption: that untouched columns stay byte-identical between
			// frames. If the engine clears the whole target to a value that
			// changes per frame, dead columns would register as changing and
			// the gap would vanish. A clear is spatially uniform and rendered
			// content is not, so "changes between frames but matches its
			// neighbours" detects exactly that case.
			std::vector<uint8_t> variation;
			uint64_t signature = 0;
			uint32_t width = 0;
			uint32_t bytesPerPixel = 0;
			uint32_t ring = 0;
			uint32_t frames = 0;
			uint32_t samples = 0;
			bool havePrevious = false;
			bool reported = false;
			bool announced = false;
		};

		// Only the formats a Skyrim scene target actually uses. Anything else
		// reports once and disables itself rather than guessing a stride and
		// producing a confident wrong answer.
		static uint32_t BytesPerPixel(DXGI_FORMAT a_format)
		{
			switch (a_format) {
			case DXGI_FORMAT_R11G11B10_FLOAT:
			case DXGI_FORMAT_R8G8B8A8_UNORM:
			case DXGI_FORMAT_R8G8B8A8_UNORM_SRGB:
			case DXGI_FORMAT_R8G8B8A8_TYPELESS:
			case DXGI_FORMAT_R10G10B10A2_UNORM:
			case DXGI_FORMAT_R16G16_FLOAT:
				return 4u;
			case DXGI_FORMAT_R16G16B16A16_FLOAT:
			case DXGI_FORMAT_R16G16B16A16_TYPELESS:
				return 8u;
			case DXGI_FORMAT_R32G32B32A32_FLOAT:
				return 16u;
			default:
				return 0u;
			}
		}

		static void Reset(Slot& a_slot, uint64_t a_signature, uint32_t a_width, uint32_t a_bytesPerPixel)
		{
			for (auto& staging : a_slot.staging)
				staging = nullptr;
			a_slot.previous.assign(static_cast<size_t>(a_width) * a_bytesPerPixel, 0u);
			a_slot.changes.assign(a_width, 0u);
			a_slot.variation.assign(a_width, 0u);
			a_slot.signature = a_signature;
			a_slot.width = a_width;
			a_slot.bytesPerPixel = a_bytesPerPixel;
			a_slot.ring = 0;
			a_slot.frames = 0;
			a_slot.samples = 0;
			a_slot.havePrevious = false;
			a_slot.reported = false;
			a_slot.announced = false;
		}

		// Collapse the per-column activity into readable pixel ranges. A gap
		// wider than a few pixels is the whole finding, so report gaps
		// explicitly rather than leaving them to be inferred from the ranges.
		static std::string DescribeActive(const std::vector<uint8_t>& a_changes, size_t& o_widestGap)
		{
			std::string ranges;
			std::string gaps;
			size_t index = 0;
			const size_t count = a_changes.size();
			bool firstRange = true;
			bool firstGap = true;
			size_t lastActiveEnd = 0;
			o_widestGap = 0;
			const auto isActive = [&](size_t i) { return a_changes[i] >= kMinChanges; };
			while (index < count) {
				while (index < count && !isActive(index))
					++index;
				if (index >= count)
					break;
				const size_t start = index;
				while (index < count && isActive(index))
					++index;
				if (!firstRange && start - lastActiveEnd >= kMinGapWidth) {
					gaps += std::format("{}{}-{}", firstGap ? "" : ", ", lastActiveEnd, start);
					firstGap = false;
					o_widestGap = std::max(o_widestGap, start - lastActiveEnd);
				}
				ranges += std::format("{}{}-{}", firstRange ? "" : ", ", start, index);
				firstRange = false;
				lastActiveEnd = index;
			}
			if (ranges.empty())
				ranges = "none";
			return std::format("active px {} | gaps {}", ranges, gaps.empty() ? "none" : gaps);
		}

		void Probe(
			Slot& a_slot,
			ID3D11Resource* a_resource,
			UINT a_subresource,
			uint64_t a_signature,
			const char* a_label,
			const char* a_context,
			uint32_t a_renderWidth = 0u,
			uint32_t a_allocWidth = 0u,
			uint32_t a_validHeight = 0u)
		{
			auto* device = globals::d3d::device;
			auto* context = globals::d3d::context;
			if (!device || !context || !a_resource)
				return;

			D3D11_TEXTURE2D_DESC desc{};
			if (!TryGetTexture2DDesc(a_resource, desc))
				return;
			if (!desc.Width || !desc.Height || desc.Width > kMaxWidth || desc.SampleDesc.Count != 1) {
				// Silence here would look identical to "the probe never ran",
				// which is the failure mode that wastes a whole session.
				static bool loggedShape = false;
				if (!loggedShape) {
					loggedShape = true;
					logger::warn(
						"[EnvProbe] {} is {}x{} samples={}; probe cannot read it and is disabled for it.",
						a_label, desc.Width, desc.Height, desc.SampleDesc.Count);
				}
				return;
			}

			const uint32_t bytesPerPixel = BytesPerPixel(desc.Format);
			if (!bytesPerPixel) {
				static bool loggedFormat = false;
				if (!loggedFormat) {
					loggedFormat = true;
					logger::warn(
						"[EnvProbe] {} has format {} with no known stride; probe disabled for it.",
						a_label,
						static_cast<int>(desc.Format));
				}
				return;
			}

			if (a_slot.signature != a_signature || a_slot.width != desc.Width ||
				a_slot.bytesPerPixel != bytesPerPixel) {
				// Say so when a window is abandoned part-way. Otherwise a session
				// spent changing preset every few seconds produces no output at
				// all and looks like a broken build rather than a rushed run.
				if (a_slot.frames > 0 && !a_slot.reported) {
					logger::info(
						"[EnvProbe] {} abandoned after {} of {} frames because the geometry changed. "
						"Hold one preset longer than that to get a verdict.",
						a_label, a_slot.frames, kProbeFrames);
				}
				Reset(a_slot, a_signature, desc.Width, bytesPerPixel);
			}
			if (a_slot.reported)
				return;

			if (!a_slot.announced) {
				a_slot.announced = true;
				logger::info(
					"[EnvProbe] {} armed: {}x{} | {} | sampling {} frames, move your head normally.",
					a_label, desc.Width, desc.Height, a_context, kProbeFrames);
			}

			if (!a_slot.staging[a_slot.ring]) {
				D3D11_TEXTURE2D_DESC stagingDesc{};
				stagingDesc.Width = desc.Width;
				stagingDesc.Height = 1;
				stagingDesc.MipLevels = 1;
				stagingDesc.ArraySize = 1;
				stagingDesc.Format = desc.Format;
				stagingDesc.SampleDesc.Count = 1;
				stagingDesc.Usage = D3D11_USAGE_STAGING;
				stagingDesc.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
				if (FAILED(device->CreateTexture2D(&stagingDesc, nullptr, a_slot.staging[a_slot.ring].put())))
					return;
			}

			// A middle scanline of the VALID region, not of the texture.
			//
			// Using the texture height put the row at allocationHeight/2, which at
			// UltraPerformance is exactly outside a render height of the same value -
			// so both eye buffers reported "active none" and looked like a finding.
			// Codex caught this independently. One row is still enough, because the
			// question is about columns.
			const UINT validHeight = a_validHeight ? std::min<uint32_t>(a_validHeight, desc.Height) : desc.Height;
			const UINT row = std::max<UINT>(1u, validHeight) / 2u;
			D3D11_BOX box{ 0u, row, 0u, desc.Width, row + 1u, 1u };
			context->CopySubresourceRegion(
				a_slot.staging[a_slot.ring].get(), 0, 0, 0, 0, a_resource, a_subresource, &box);

			// Read the copy from two frames ago so the map never blocks the GPU.
			const uint32_t readIndex = (a_slot.ring + 1u) % kRingDepth;
			if (a_slot.staging[readIndex] && a_slot.frames >= kRingDepth - 1u) {
				D3D11_MAPPED_SUBRESOURCE mapped{};
				const HRESULT hr = context->Map(
					a_slot.staging[readIndex].get(), 0, D3D11_MAP_READ, D3D11_MAP_FLAG_DO_NOT_WAIT, &mapped);
				if (SUCCEEDED(hr) && mapped.pData) {
					const auto* bytes = static_cast<const uint8_t*>(mapped.pData);
					// Bound by the comparison buffer as well as the row: RowPitch is
					// padded, and must never index past `previous`.
					const size_t rowBytes = std::min<size_t>(
						std::min<size_t>(mapped.RowPitch, static_cast<size_t>(a_slot.width) * bytesPerPixel),
						a_slot.previous.size());
					for (size_t offset = 0; offset + bytesPerPixel <= rowBytes; offset += bytesPerPixel) {
						const size_t column = offset / bytesPerPixel;
						if (column >= a_slot.changes.size())
							break;
						// Column 0 has no left neighbour, so look right instead;
						// the leftmost column is where a real range begins and
						// must not be excluded by an edge case.
						const size_t neighbour = column == 0u ? offset + bytesPerPixel : offset - bytesPerPixel;
						if (neighbour + bytesPerPixel <= rowBytes &&
							a_slot.variation[column] < kMinChanges &&
							std::memcmp(bytes + offset, bytes + neighbour, bytesPerPixel) != 0) {
							++a_slot.variation[column];
						}
						if (a_slot.havePrevious && a_slot.changes[column] < kMinChanges &&
							std::memcmp(bytes + offset, a_slot.previous.data() + offset, bytesPerPixel) != 0) {
							++a_slot.changes[column];
						}
					}
					if (a_slot.havePrevious)
						++a_slot.samples;
					std::memcpy(a_slot.previous.data(), bytes, std::min(rowBytes, a_slot.previous.size()));
					a_slot.havePrevious = true;
					context->Unmap(a_slot.staging[readIndex].get(), 0);
				}
			}

			a_slot.ring = (a_slot.ring + 1u) % kRingDepth;
			if (++a_slot.frames < kProbeFrames)
				return;

			a_slot.reported = true;

			// Too few usable comparisons means the scene was static, not that
			// nothing was rendered. Reporting "no active columns" from that would
			// be a confident wrong answer, which is the failure this whole probe
			// exists to avoid.
			if (a_slot.samples < kMinChanges * 2u) {
				logger::warn(
					"[EnvProbe] {} INCONCLUSIVE: only {} usable samples in {} frames. The view was too "
					"static to tell rendered columns from stale ones. Re-run and keep moving.",
					a_label, a_slot.samples, a_slot.frames);
				return;
			}

			size_t widestGap = 0;
			const std::string described = DescribeActive(a_slot.changes, widestGap);

			// Test the assumption instead of trusting it. Columns that change
			// between frames while matching their neighbours are not rendered
			// content; that is what a per-frame clear to a varying value looks
			// like, and it would silently close the gap we are measuring.
			size_t changedColumns = 0;
			size_t changedButUniform = 0;
			for (size_t column = 0; column < a_slot.changes.size(); ++column) {
				if (a_slot.changes[column] < kMinChanges)
					continue;
				++changedColumns;
				if (a_slot.variation[column] < kMinChanges)
					++changedButUniform;
			}
			const bool clearConfound =
				changedColumns > 0 &&
				changedButUniform * 100u / changedColumns > 20u;
			if (clearConfound) {
				logger::warn(
					"[EnvProbe] {} SUSPECT: {} of {} changing columns are spatially uniform. That is the "
					"signature of a per-frame clear to a varying value rather than rendered content, and it "
					"would hide a real gap. Do not trust the verdict below.",
					a_label,
					changedButUniform,
					changedColumns);
			}

			std::string verdict;
			if (a_renderWidth && a_allocWidth && a_allocWidth > a_renderWidth) {
				const size_t expectedGap = (a_allocWidth - a_renderWidth) / 2u;
				// Generous tolerance: we are separating "a gap of hundreds of
				// pixels" from "no gap", not measuring the gap.
				const size_t tolerance = std::max<size_t>(kMinGapWidth, expectedGap / 4u);
				const bool gapMatches =
					widestGap + tolerance >= expectedGap && widestGap <= expectedGap + tolerance;
				verdict = std::format(
					" | predicted repacked 0-{} no gap, halves gap {} px | widest gap {} px => VERDICT {}",
					a_renderWidth,
					expectedGap,
					widestGap,
					clearConfound      ? "SUSPECT - clear confound, see warning above" :
						gapMatches     ? "ALLOCATION HALVES" :
						widestGap == 0 ? "REPACKED" :
										 "NEITHER - unexpected layout");
			}

			logger::info(
				"[EnvProbe] {} {}x{} | {} | frames {} samples {} | {}{}",
				a_label,
				desc.Width,
				desc.Height,
				a_context,
				a_slot.frames,
				a_slot.samples,
				described,
				verdict);
			logger::info(
				"[EnvProbe] {} detail: changing columns {}, of which spatially uniform {} (uniform means cleared, not drawn).",
				a_label,
				changedColumns,
				changedButUniform);
		}

		Slot mainTarget;
		Slot eyeInput[2];
		// The texture actually handed to the compositor. This is the one that
		// matters: if the scene occupies only part of it, the eye is presented
		// with the wrong field of view, which looks unremarkable on a flat
		// desktop mirror and badly wrong in a headset.
		Slot eyeOutput[2];
	};

	EnvelopeColumnProbe g_envelopeColumnProbe;

	// Phase 0A: compare the pure planner against what production computed.
	//
	// Reports on change of signature, so a steady scene produces one line per
	// distinct geometry rather than one per frame. Silence means the planner and
	// production agree on real data, which is the precondition for letting
	// production depend on it.
	void LogGeometryPolicyShadowMismatch(
		const Upscaling::RuntimeResolutionPlan& a_plan,
		const float2& a_displayCombined,
		const Upscaling::PerfModeState::BootSnapshot& a_boot,
		uint32_t a_requestedQuality,
		uint32_t a_runtimeQuality,
		bool a_renderScaleLatched,
		bool a_physicalRecovery)
	{
		if (a_displayCombined.x < 2.0f || a_displayCombined.y < 2.0f)
			return;

		VRGeometryPolicy::Inputs inputs{};
		inputs.displayPerEye = {
			static_cast<uint32_t>(a_displayCombined.x) / 2u,
			static_cast<uint32_t>(a_displayCombined.y)
		};
		inputs.phase = a_physicalRecovery ?
		                   VRGeometryPolicy::Phase::PhysicalRecovery :
		                   VRGeometryPolicy::Phase::Stable;

		if (a_renderScaleLatched) {
			// Render Scale Mode is the envelope with boot == active, so one flow
			// covers both by the diagonal identity the tests assert.
			inputs.flow = VRGeometryPolicy::Flow::HotEnvelope;
			inputs.bootQuality = a_boot.valid ? a_boot.qualityMode : a_requestedQuality;
			inputs.activeQuality = a_requestedQuality;
		} else {
			inputs.flow = VRGeometryPolicy::Flow::RenderScaleOff;
			inputs.bootQuality = a_runtimeQuality;
			inputs.activeQuality = a_runtimeQuality;
		}

		const auto decision = VRGeometryPolicy::Derive(inputs);
		const auto toExtent = [](const float2& a_value) {
			return VRGeometryPolicy::Extent{
				static_cast<uint32_t>(a_value.x),
				static_cast<uint32_t>(a_value.y)
			};
		};
		const auto toTaggedExtent = [](const auto& a_extent) {
			return VRGeometryPolicy::Extent{
				static_cast<uint32_t>(a_extent.width),
				static_cast<uint32_t>(a_extent.height)
			};
		};

		// RS-off never records an allocation - only the render-scale branch sets
		// engineAllocationSize - so falling back to engineRenderSize made every
		// RS-off frame look like a mismatch when the two simply are not the same
		// field. The policy is right that the allocation is the display there;
		// production just does not track it. Compare only what production
		// actually computes.
		const bool productionTracksAllocation = a_plan.engineAllocationSize.width > 0.0f;
		const auto productionAllocation = productionTracksAllocation ?
		                                      toTaggedExtent(a_plan.engineAllocationSize) :
		                                      decision.plan.allocationCombined;
		const auto productionRender = toTaggedExtent(a_plan.engineRenderSize);
		const auto productionOutput = toExtent(a_plan.finalOutputSize);

		const bool allocationAgrees = productionAllocation == decision.plan.allocationCombined;
		const bool renderAgrees = productionRender == decision.plan.renderCombined;
		const bool outputAgrees = productionOutput == decision.plan.outputCombined;
		// A quality that does not fit its allocation is the one case production
		// and the policy are expected to differ: production silently returns the
		// allocation, the policy reports RelatchRequired and keeps the requested
		// size. Recorded rather than treated as a defect, because deciding which
		// is right belongs to phase 2.
		const bool expectedRelatchDivergence =
			decision.action == VRGeometryPolicy::Action::RelatchRequired;

		// Under RS-off the plan's render size comes from resolveVendorDynamicRenderSize(),
		// which reads resolutionScale - and resolutionScale is written later in
		// the frame by ConfigureUpscaling. So for exactly one frame after a
		// quality change the plan still carries the previous quality's render
		// size, then catches up. Measured at ~18 ms. Benign and self-correcting,
		// but it is production behaviour rather than a mapping error, so it is
		// classified rather than reported as a fault.
		const bool expectedRenderLag =
			!a_renderScaleLatched && allocationAgrees && outputAgrees && !renderAgrees;

		if (allocationAgrees && renderAgrees && outputAgrees)
			return;

		static uint64_t loggedSignature = 0xFFFFFFFFFFFFFFFFull;
		const uint64_t signature =
			(static_cast<uint64_t>(productionAllocation.width) << 44) ^
			(static_cast<uint64_t>(productionRender.width) << 28) ^
			(static_cast<uint64_t>(decision.plan.renderCombined.width) << 12) ^
			(static_cast<uint64_t>(inputs.bootQuality) << 8) ^
			static_cast<uint64_t>(inputs.activeQuality);
		if (signature == loggedSignature)
			return;
		loggedSignature = signature;

		logger::warn(
			"[GeomShadow] flow={} phase={} boot={} active={} display {}x{} | "
			"production alloc {}x{} render {}x{} output {}x{} | "
			"policy alloc {}x{} render {}x{} output {}x{} | action={} | {}",
			a_renderScaleLatched ? "envelope" : "rs-off",
			a_physicalRecovery ? "recovery" : "stable",
			inputs.bootQuality,
			inputs.activeQuality,
			inputs.displayPerEye.width,
			inputs.displayPerEye.height,
			productionAllocation.width, productionAllocation.height,
			productionRender.width, productionRender.height,
			productionOutput.width, productionOutput.height,
			decision.plan.allocationCombined.width, decision.plan.allocationCombined.height,
			decision.plan.renderCombined.width, decision.plan.renderCombined.height,
			decision.plan.outputCombined.width, decision.plan.outputCombined.height,
			static_cast<int>(decision.action),
			expectedRelatchDivergence ? "EXPECTED: requested quality does not fit the allocation" :
				expectedRenderLag     ? "EXPECTED: RS-off render size trails the quality change by one frame" :
										"UNEXPECTED: the mapping from runtime state to policy inputs is wrong");
	}

	// Auto-debug: emit a submit-decision record when its content changes.
	//
	// Per frame per eye would be 144 lines a second and unreadable; once per
	// distinct decision is a legible flow that can be reconstructed after the
	// fact. A bounded total stops a long session filling the disk.
	void LogSubmitDecisionIfChanged(uint32_t a_eyeIndex, const std::string& a_record)
	{
		static constexpr uint32_t kMaxRecords = 400u;
		static std::string lastRecord[2];
		static uint32_t emitted = 0;
		const uint32_t slot = a_eyeIndex > 0u ? 1u : 0u;
		if (a_record == lastRecord[slot])
			return;
		if (emitted >= kMaxRecords) {
			static bool loggedCap = false;
			if (!loggedCap) {
				loggedCap = true;
				logger::warn(
					"[SubmitTrace] record cap {} reached; further decisions are not logged. "
					"The flow up to this point is complete.",
					kMaxRecords);
			}
			return;
		}
		lastRecord[slot] = a_record;
		++emitted;
		logger::info("[SubmitTrace] eye {} | {}", a_eyeIndex, a_record);
	}

	// Separate dedupe state from the decision record: the output can change
	// while the decision does not, and sharing one "last seen" string would let
	// either hide the other.
	void LogSubmitOutputIfChanged(uint32_t a_eyeIndex, const std::string& a_record)
	{
		static constexpr uint32_t kMaxRecords = 200u;
		static std::string lastRecord[2];
		static uint32_t emitted = 0;
		const uint32_t slot = a_eyeIndex > 0u ? 1u : 0u;
		if (a_record == lastRecord[slot] || emitted >= kMaxRecords)
			return;
		lastRecord[slot] = a_record;
		++emitted;
		logger::info("[SubmitOut] eye {} | {}", a_eyeIndex, a_record);
	}

	bool IsCommonVendorTextureCompatible(
		const Texture2D* a_texture,
		const D3D11_TEXTURE2D_DESC& a_expected)
	{
		if (!a_texture ||
			!a_texture->resource ||
			!a_texture->srv ||
			!a_texture->uav ||
			!globals::d3d::device) {
			return false;
		}

		winrt::com_ptr<ID3D11Device> textureDevice;
		a_texture->resource->GetDevice(textureDevice.put());
		if (GetCOMIdentityAddress(textureDevice.get()) !=
			GetCOMIdentityAddress(globals::d3d::device)) {
			return false;
		}

		D3D11_TEXTURE2D_DESC actual{};
		a_texture->resource->GetDesc(&actual);
		constexpr UINT requiredBindFlags =
			D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_UNORDERED_ACCESS;
		return actual.Width == a_expected.Width &&
		       actual.Height == a_expected.Height &&
		       actual.MipLevels == a_expected.MipLevels &&
		       actual.ArraySize == a_expected.ArraySize &&
		       actual.Format == a_expected.Format &&
		       actual.SampleDesc.Count == a_expected.SampleDesc.Count &&
		       actual.SampleDesc.Quality == a_expected.SampleDesc.Quality &&
		       (actual.BindFlags & requiredBindFlags) == requiredBindFlags;
	}

	D3D11_TEXTURE2D_DESC BuildFlatRuntimeFsrDepthDesc(
		const D3D11_TEXTURE2D_DESC& a_mainDesc)
	{
		D3D11_TEXTURE2D_DESC depthDesc{};
		depthDesc.Width = a_mainDesc.Width;
		depthDesc.Height = a_mainDesc.Height;
		depthDesc.MipLevels = 1;
		depthDesc.ArraySize = 1;
		depthDesc.Format = DXGI_FORMAT_R32_FLOAT;
		depthDesc.SampleDesc.Count = 1;
		depthDesc.Usage = D3D11_USAGE_DEFAULT;
		depthDesc.BindFlags =
			D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_UNORDERED_ACCESS;
		return depthDesc;
	}

	template <class T, std::size_t N>
	bool ViewsReferenceEitherResourceAndRelease(
		std::array<T*, N>& a_views,
		std::uintptr_t a_firstIdentity,
		std::uintptr_t a_secondIdentity = 0)
	{
		bool referencesResource = false;
		for (auto*& view : a_views) {
			if (!view)
				continue;

			winrt::com_ptr<ID3D11Resource> resource;
			view->GetResource(resource.put());
			const auto identity = GetCOMIdentityAddress(resource.get());
			referencesResource =
				referencesResource ||
				(identity != 0 &&
					(identity == a_firstIdentity ||
						(a_secondIdentity != 0 && identity == a_secondIdentity)));
			view->Release();
			view = nullptr;
		}
		return referencesResource;
	}

	bool HasVRPostLoadCandidateRepairBindingConflict(
		ID3D11DeviceContext* a_context,
		std::uintptr_t a_candidateIdentity,
		std::uintptr_t a_depthIdentity)
	{
		if (!a_context || !a_candidateIdentity || !a_depthIdentity)
			return true;

		const auto shaderStageReadsCandidate = [&](auto&& a_getResources) {
			std::array<
				ID3D11ShaderResourceView*,
				D3D11_COMMONSHADER_INPUT_RESOURCE_SLOT_COUNT>
				views{};
			a_getResources(views.data());
			return ViewsReferenceEitherResourceAndRelease(
				views,
				a_candidateIdentity);
		};
		constexpr UINT shaderResourceCount =
			D3D11_COMMONSHADER_INPUT_RESOURCE_SLOT_COUNT;
		if (shaderStageReadsCandidate([&](ID3D11ShaderResourceView** a_views) {
				a_context->VSGetShaderResources(0, shaderResourceCount, a_views);
			}) ||
			shaderStageReadsCandidate([&](ID3D11ShaderResourceView** a_views) {
				a_context->HSGetShaderResources(0, shaderResourceCount, a_views);
			}) ||
			shaderStageReadsCandidate([&](ID3D11ShaderResourceView** a_views) {
				a_context->DSGetShaderResources(0, shaderResourceCount, a_views);
			}) ||
			shaderStageReadsCandidate([&](ID3D11ShaderResourceView** a_views) {
				a_context->GSGetShaderResources(0, shaderResourceCount, a_views);
			}) ||
			shaderStageReadsCandidate([&](ID3D11ShaderResourceView** a_views) {
				a_context->PSGetShaderResources(0, shaderResourceCount, a_views);
			}) ||
			shaderStageReadsCandidate([&](ID3D11ShaderResourceView** a_views) {
				a_context->CSGetShaderResources(0, shaderResourceCount, a_views);
			})) {
			return true;
		}

		std::array<
			ID3D11UnorderedAccessView*,
			D3D11_PS_CS_UAV_REGISTER_COUNT>
			computeUAVs{};
		a_context->CSGetUnorderedAccessViews(
			0,
			static_cast<UINT>(computeUAVs.size()),
			computeUAVs.data());
		if (ViewsReferenceEitherResourceAndRelease(
				computeUAVs,
				a_candidateIdentity,
				a_depthIdentity)) {
			return true;
		}

		std::array<
			ID3D11RenderTargetView*,
			D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT>
			renderTargets{};
		ID3D11DepthStencilView* depthStencil = nullptr;
		a_context->OMGetRenderTargets(
			static_cast<UINT>(renderTargets.size()),
			renderTargets.data(),
			&depthStencil);
		const bool renderTargetConflict =
			ViewsReferenceEitherResourceAndRelease(
				renderTargets,
				a_candidateIdentity,
				a_depthIdentity);
		bool depthStencilConflict = false;
		if (depthStencil) {
			winrt::com_ptr<ID3D11Resource> resource;
			depthStencil->GetResource(resource.put());
			const auto identity = GetCOMIdentityAddress(resource.get());
			if (identity == a_candidateIdentity) {
				depthStencilConflict = true;
			} else if (identity == a_depthIdentity) {
				D3D11_DEPTH_STENCIL_VIEW_DESC desc{};
				depthStencil->GetDesc(&desc);
				depthStencilConflict =
					(desc.Flags & D3D11_DSV_READ_ONLY_DEPTH) == 0;
			}
			depthStencil->Release();
		}
		if (renderTargetConflict || depthStencilConflict)
			return true;

		std::array<
			ID3D11UnorderedAccessView*,
			D3D11_PS_CS_UAV_REGISTER_COUNT>
			outputMergerUAVs{};
		a_context->OMGetRenderTargetsAndUnorderedAccessViews(
			0,
			nullptr,
			nullptr,
			0,
			static_cast<UINT>(outputMergerUAVs.size()),
			outputMergerUAVs.data());
		return ViewsReferenceEitherResourceAndRelease(
			outputMergerUAVs,
			a_candidateIdentity,
			a_depthIdentity);
	}

	bool IsVRRenderScaleResolutionPlanExact(
		const Upscaling::RuntimeResolutionPlan& a_plan,
		const Upscaling::PerfModeState::BootSnapshot& a_boot)
	{
		if (!a_boot.renderEyeWidth ||
			!a_boot.renderEyeHeight ||
			!a_boot.displayEyeWidth ||
			!a_boot.displayEyeHeight ||
			a_boot.renderEyeWidth > std::numeric_limits<uint32_t>::max() / 2u ||
			a_boot.displayEyeWidth > std::numeric_limits<uint32_t>::max() / 2u) {
			return false;
		}

		const uint32_t renderWidth = a_boot.renderEyeWidth * 2u;
		const uint32_t displayWidth = a_boot.displayEyeWidth * 2u;
		const auto matchesDimension = [](float a_actual, uint32_t a_expected) {
			return std::isfinite(a_actual) &&
			       a_actual > 0.0f &&
			       a_actual == static_cast<float>(a_expected);
		};
		// Hot-Envelope: this asks whether the PHYSICAL plan still matches the boot
		// contract, so it must compare the allocation. engineRenderSize answered
		// that only because the two were always equal; under an envelope the render
		// extent is deliberately smaller and this would report "not exact" forever.
		//
		// engineAllocationSize is zero on plans that never set it, so fall back to
		// engineRenderSize and keep the original behaviour exactly.
		const float allocationX = a_plan.engineAllocationSize.width > 0.0f ?
		                              a_plan.engineAllocationSize.width :
		                              a_plan.engineRenderSize.width;
		const float allocationY = a_plan.engineAllocationSize.height > 0.0f ?
		                              a_plan.engineAllocationSize.height :
		                              a_plan.engineRenderSize.height;
		return matchesDimension(allocationX, renderWidth) &&
		       matchesDimension(allocationY, a_boot.renderEyeHeight) &&
		       matchesDimension(a_plan.finalOutputSize.x, displayWidth) &&
		       matchesDimension(a_plan.finalOutputSize.y, a_boot.displayEyeHeight);
	}

	bool IsVRRenderScalePhysicalVendorContractExact(
		const Upscaling::VRRenderScaleTransitionSnapshot& a_transition,
		const Upscaling::PerfModeState::BootSnapshot& a_boot,
		Upscaling::UpscaleMethod a_runtimeMethod)
	{
		const auto& applied = a_transition.applied;
		return IsVendorUpscalingMethod(a_runtimeMethod) &&
		       (a_transition.state == Upscaling::VRRenderScaleTransitionState::Stabilizing ||
				   a_transition.state == Upscaling::VRRenderScaleTransitionState::Active) &&
		       a_boot.valid &&
		       a_boot.active &&
		       a_boot.renderScaleEnabled &&
		       a_boot.perfModeEnabled &&
		       a_boot.generation != 0 &&
		       a_boot.method == a_runtimeMethod &&
		       applied.valid &&
		       applied.active &&
		       applied.transitionEpoch != 0 &&
		       a_transition.targetEpoch == applied.transitionEpoch &&
		       applied.contractGeneration == a_boot.generation &&
		       applied.method == a_runtimeMethod &&
		       ClampQualityModeUInt(applied.qualityMode) ==
		           ClampQualityModeUInt(a_boot.qualityMode) &&
		       (a_runtimeMethod != Upscaling::UpscaleMethod::kDLSS ||
				   Upscaling::ClampDLSSPresetUInt(applied.dlssPreset) ==
					   Upscaling::ClampDLSSPresetUInt(a_boot.dlssPreset)) &&
		       applied.renderScaleModeEnabled &&
		       applied.perfModeEnabled &&
		       applied.renderEyeWidth == a_boot.renderEyeWidth &&
		       applied.renderEyeHeight == a_boot.renderEyeHeight &&
		       applied.displayEyeWidth == a_boot.displayEyeWidth &&
		       applied.displayEyeHeight == a_boot.displayEyeHeight;
	}

	// Physical truth is intentionally independent from the presentation gate.
	// During a serialized COC handoff submitStageVendorAllowed is false until
	// this exact contract qualifies the gate, so folding it into physical
	// equality creates a self-blocking proof cycle.
	bool IsVRRenderScaleAppliedVendorContractExact(
		const Upscaling::VRRenderScaleTransitionSnapshot& a_transition,
		const Upscaling::PerfModeState::BootSnapshot& a_boot,
		Upscaling::UpscaleMethod a_runtimeMethod)
	{
		return a_boot.submitStageVendorAllowed &&
		       IsVRRenderScalePhysicalVendorContractExact(
			   a_transition,
			   a_boot,
			   a_runtimeMethod);
	}

	bool IsVRFixedVendorResolutionPlanOwnerExact(
		const Upscaling::RuntimeResolutionPlan& a_plan,
		Upscaling::UpscaleMethod a_runtimeMethod);

	struct VRSubmitStageMaskRepairProof
	{
		Upscaling::VRRenderScaleTransitionState transitionState =
			Upscaling::VRRenderScaleTransitionState::Idle;
		Upscaling::UpscaleMethod method = Upscaling::UpscaleMethod::kNONE;
		uint32_t generation = 0;
		std::uintptr_t colorIdentity = 0;
		bool mayBypassMaskDeferral = false;
	};

	std::optional<VRSubmitStageMaskRepairProof>
	ValidateVRSubmitStageMaskRepairContract(
		const Upscaling& a_upscaling,
		const State* a_state,
		uint32_t a_eyeIndex,
		ID3D11UnorderedAccessView* a_colorUAV,
		ID3D11ShaderResourceView* a_depthSRV,
		uint32_t a_depthWidth,
		uint32_t a_depthHeight,
		uint32_t a_colorWidth,
		uint32_t a_colorHeight,
		uint32_t a_depthOffsetX,
		uint32_t a_colorOffsetX,
		uint32_t a_depthOffsetY,
		uint32_t a_colorOffsetY)
	{
		if (!globals::game::isVR ||
			!a_state ||
			a_eyeIndex >= 2 ||
			!a_colorUAV ||
			!a_depthSRV ||
			!a_upscaling.IsVRInitialLoadPresentationProtectionActive() ||
			!a_upscaling.IsVRPostLoadCompositorHoldActive() ||
			IsMainMenuContextActive() ||
			IsLoadingMenuContextActive() ||
			IsNonLoadingVRMenuPresentationContextActive() ||
			IsSaveLoadTransitionContextActive(a_state) ||
			a_state->pendingPostLoadRuntimeReset ||
			a_upscaling.postLoadRuntimeResetPending.load(std::memory_order_acquire) ||
			a_upscaling.pendingPerfModeRenderTargetRecreate.load(std::memory_order_acquire) ||
			a_upscaling.perfModeRenderTargetRecreateInProgress.load(std::memory_order_acquire) ||
			a_upscaling.HasPendingVRUpscalingTransition() ||
			a_upscaling.pendingVRFpsStabilizerSyncFrame.load(std::memory_order_acquire) != 0 ||
			HasUnresolvedVRFpsStabilizerSyncForCurrentLoad(a_upscaling) ||
			a_upscaling.IsSubmitStageDeviceLost()) {
			return std::nullopt;
		}

		const uint32_t currentFrame = std::max(a_state->frameCount, 1u);
		if (!HasCompletedVRWorldFrameAfterLatestLoad(a_state) ||
			a_state->lastWorldRenderFrame != currentFrame ||
			a_state->lastCompletedWorldRenderFrame != currentFrame) {
			return std::nullopt;
		}

		const auto runtimeMethod = a_upscaling.GetRuntimeUpscaleMethod();
		const auto boot = a_upscaling.perfMode.GetBootSnapshot();
		const auto transition = a_upscaling.GetVRRenderScaleTransitionSnapshot();
		const auto& plan = a_upscaling.GetRuntimeResolutionPlan();
		const auto& output = a_upscaling.vrIntermediateColorOut[a_eyeIndex];
		const bool activeRenderScaleContract =
			a_upscaling.IsVRRenderScaleModeLatched() &&
			a_upscaling.IsPresentationUpscalingActive() &&
			IsVRRenderScaleAppliedVendorContractExact(
				transition,
				boot,
				runtimeMethod) &&
			plan.owner == Upscaling::ResolutionOwner::VRRenderScaleMode &&
			IsVRRenderScaleResolutionPlanExact(plan, boot);
		const auto& applied = transition.applied;
		const bool stabilizingInactiveContract =
			transition.state ==
				Upscaling::VRRenderScaleTransitionState::Stabilizing &&
			applied.valid &&
			!applied.active &&
			applied.transitionEpoch != 0 &&
			transition.targetEpoch == applied.transitionEpoch &&
			applied.method == runtimeMethod &&
			applied.renderEyeWidth == applied.displayEyeWidth &&
			applied.renderEyeHeight == applied.displayEyeHeight;
		const bool fixedVendorSubmitStage =
			!a_upscaling.IsVRRenderScaleModeLatched() &&
			a_upscaling.IsPresentationUpscalingActive() &&
			IsVRFixedVendorRuntimeStableForPostLoad(a_upscaling) &&
			IsVRFixedVendorResolutionPlanOwnerExact(plan, runtimeMethod);
		if (a_upscaling.GetConfiguredUpscaleMethodForTransition() != runtimeMethod ||
			(!activeRenderScaleContract && !fixedVendorSubmitStage) ||
			HasPendingVRVendorRuntimeReset(a_upscaling, runtimeMethod) ||
			!plan.vendorMethod ||
			plan.upscaleMethod != runtimeMethod ||
			plan.menuContextActive ||
			plan.knownMenuContextActive ||
			plan.loadingMenuActive ||
			plan.perfModeRestartRequired ||
			!output ||
			!output->resource ||
			!output->uav ||
			a_colorUAV != output->uav.get()) {
			return std::nullopt;
		}

		winrt::com_ptr<ID3D11Resource> colorResource;
		winrt::com_ptr<ID3D11Resource> depthResource;
		a_colorUAV->GetResource(colorResource.put());
		a_depthSRV->GetResource(depthResource.put());
		const auto colorIdentity = GetCOMIdentityAddress(colorResource.get());
		if (!colorResource || !depthResource ||
			colorIdentity == 0 ||
			GetCOMIdentityAddress(output->resource.get()) !=
				colorIdentity) {
			return std::nullopt;
		}

		const uint32_t renderEyeWidth =
			activeRenderScaleContract ?
				boot.renderEyeWidth :
				std::max<uint32_t>(
					1u,
					ClampPositiveDimension(plan.engineRenderSize.width) / 2u);
		const uint32_t renderEyeHeight =
			activeRenderScaleContract ?
				boot.renderEyeHeight :
				ClampPositiveDimension(plan.engineRenderSize.height);
		const uint32_t displayEyeWidth =
			activeRenderScaleContract ?
				boot.displayEyeWidth :
				std::max<uint32_t>(
					1u,
					ClampPositiveDimension(plan.finalOutputSize.x) / 2u);
		const uint32_t displayEyeHeight =
			activeRenderScaleContract ?
				boot.displayEyeHeight :
				ClampPositiveDimension(plan.finalOutputSize.y);
		const uint32_t combinedRenderWidth =
			ClampPositiveDimension(plan.engineRenderSize.width);
		const uint32_t combinedDisplayWidth =
			ClampPositiveDimension(plan.finalOutputSize.x);
		// Physical screenSize follows the recreated engine targets in Render Scale;
		// fixed-vendor upscaling leaves those targets at compositor display size.
		const uint32_t stateScreenWidth =
			activeRenderScaleContract ? combinedRenderWidth : combinedDisplayWidth;
		const uint32_t stateScreenHeight =
			activeRenderScaleContract ? renderEyeHeight : displayEyeHeight;
		if (!renderEyeWidth ||
			!renderEyeHeight ||
			!displayEyeWidth ||
			!displayEyeHeight ||
			(combinedRenderWidth & 1u) != 0 ||
			(combinedDisplayWidth & 1u) != 0 ||
			combinedRenderWidth != renderEyeWidth * 2u ||
			combinedDisplayWidth != displayEyeWidth * 2u ||
			ClampPositiveDimension(a_state->screenSize.x) !=
				stateScreenWidth ||
			ClampPositiveDimension(a_state->screenSize.y) !=
				stateScreenHeight) {
			return std::nullopt;
		}

		D3D11_TEXTURE2D_DESC colorDesc{};
		D3D11_TEXTURE2D_DESC depthDesc{};
		if (!TryGetTexture2DDesc(colorResource.get(), colorDesc) ||
			!TryGetTexture2DDesc(depthResource.get(), depthDesc) ||
			colorDesc.ArraySize != 1 ||
			colorDesc.MipLevels != 1 ||
			colorDesc.SampleDesc.Count != 1 ||
			colorDesc.Width != displayEyeWidth ||
			colorDesc.Height != displayEyeHeight ||
			depthDesc.ArraySize != 1 ||
			depthDesc.MipLevels != 1 ||
			depthDesc.SampleDesc.Count != 1 ||
			a_colorWidth != displayEyeWidth ||
			a_colorHeight != displayEyeHeight ||
			a_colorOffsetX != 0 ||
			a_colorOffsetY != 0 ||
			a_depthWidth != renderEyeWidth ||
			a_depthHeight != renderEyeHeight ||
			a_depthOffsetY != 0) {
			return std::nullopt;
		}

		auto* renderer = globals::game::renderer;
		if (!renderer)
			return std::nullopt;
		auto& mainDepth =
			renderer->GetDepthStencilData().depthStencils[RE::RENDER_TARGETS_DEPTHSTENCIL::kMAIN];
		if (!mainDepth.texture ||
			!mainDepth.depthSRV ||
			a_depthSRV != mainDepth.depthSRV ||
			GetCOMIdentityAddress(depthResource.get()) !=
				GetCOMIdentityAddress(mainDepth.texture)) {
			return std::nullopt;
		}

		const bool exactDepthLayout =
			depthDesc.Height == renderEyeHeight &&
			((depthDesc.Width == renderEyeWidth && a_depthOffsetX == 0) ||
				(depthDesc.Width == combinedRenderWidth &&
					a_depthOffsetX == a_eyeIndex * renderEyeWidth));
		if (!exactDepthLayout)
			return std::nullopt;
		// Preserve the original render-scale handoff rule while extending the same
		// proof type to PR12's fixed-vendor path. Stabilizing owns the mask deferral,
		// so its exact submit-stage repair is the evidence that may retire it.
		const bool exactStabilizingRenderScaleContract =
			activeRenderScaleContract &&
			transition.state ==
				Upscaling::VRRenderScaleTransitionState::Stabilizing;

		return VRSubmitStageMaskRepairProof{
			transition.state,
			runtimeMethod,
			activeRenderScaleContract ? boot.generation : 0u,
			colorIdentity,
			exactStabilizingRenderScaleContract ||
				(fixedVendorSubmitStage && stabilizingInactiveContract)
		};
	}

	bool IsVRFixedVendorResolutionPlanOwnerExact(
		const Upscaling::RuntimeResolutionPlan& a_plan,
		Upscaling::UpscaleMethod a_runtimeMethod)
	{
		if (!a_plan.vendorMethod ||
			a_plan.upscaleMethod != a_runtimeMethod) {
			return false;
		}

		if (a_plan.owner == Upscaling::ResolutionOwner::VendorDynamicResolution)
			return true;

		// Native AA/DLAA is still a live vendor evaluation, but its 1:1
		// resolution plan correctly remains Native because no downscale is
		// active. Accept only that exact 1:1 quality-zero contract.
		if (a_plan.owner != Upscaling::ResolutionOwner::Native ||
			a_plan.qualityMode != 0 ||
			!std::isfinite(a_plan.engineRenderSize.width) ||
			!std::isfinite(a_plan.engineRenderSize.height) ||
			!std::isfinite(a_plan.finalOutputSize.x) ||
			!std::isfinite(a_plan.finalOutputSize.y) ||
			a_plan.engineRenderSize.width <= 0.0f ||
			a_plan.engineRenderSize.height <= 0.0f ||
			a_plan.finalOutputSize.x <= 0.0f ||
			a_plan.finalOutputSize.y <= 0.0f) {
			return false;
		}

		return ClampPositiveDimension(a_plan.engineRenderSize.width) ==
		           ClampPositiveDimension(a_plan.finalOutputSize.x) &&
		       ClampPositiveDimension(a_plan.engineRenderSize.height) ==
		           ClampPositiveDimension(a_plan.finalOutputSize.y);
	}

	bool IsVRFixedVendorMaskRepairContractExact(
		const Upscaling& a_upscaling,
		const State* a_state,
		uint32_t a_eyeIndex,
		ID3D11UnorderedAccessView* a_colorUAV,
		ID3D11ShaderResourceView* a_depthSRV,
		uint32_t a_depthWidth,
		uint32_t a_depthHeight,
		uint32_t a_colorWidth,
		uint32_t a_colorHeight,
		uint32_t a_depthOffsetX,
		uint32_t a_colorOffsetX,
		uint32_t a_depthOffsetY,
		uint32_t a_colorOffsetY,
		bool a_saveLoadException)
	{
		// Keep both the save-load exception and settled-frame proof fail-closed:
		// the live per-eye vendor path, current plan, dimensions, offsets, and
		// exact color/depth resources must all agree.
		if (!globals::game::isVR ||
			!a_state ||
			!a_colorUAV ||
			!a_depthSRV ||
			IsSaveLoadTransitionContextActive(a_state) != a_saveLoadException ||
			a_state->pendingPostLoadRuntimeReset ||
			IsLoadingMenuContextActive() ||
			IsNonLoadingVRMenuPresentationContextActive() ||
			HasUnresolvedVRFpsStabilizerSyncForCurrentLoad(a_upscaling) ||
			!IsVRFixedVendorRuntimeStableForPostLoad(a_upscaling)) {
			return false;
		}

		const uint32_t currentFrame = std::max(a_state->frameCount, 1u);
		const uint32_t saveLoadStartFrame =
			a_state->saveLoadSafeModeStartFrame.load(std::memory_order_acquire);
		if (!HasCompletedVRWorldFrameAfterLatestLoad(a_state) ||
			(saveLoadStartFrame != 0 &&
				a_state->lastCompletedWorldRenderFrame <= saveLoadStartFrame) ||
			a_state->lastWorldRenderFrame != currentFrame) {
			return false;
		}

		const auto runtimeMethod = a_upscaling.GetRuntimeUpscaleMethod();
		const auto& plan = a_upscaling.GetRuntimeResolutionPlan();
		if (!IsVRFixedVendorResolutionPlanOwnerExact(plan, runtimeMethod) ||
			plan.knownMenuContextActive ||
			plan.menuContextActive ||
			plan.loadingMenuActive ||
			plan.perfModeRestartRequired ||
			!std::isfinite(plan.finalOutputSize.x) ||
			!std::isfinite(plan.finalOutputSize.y) ||
			!std::isfinite(plan.engineRenderSize.width) ||
			!std::isfinite(plan.engineRenderSize.height) ||
			plan.finalOutputSize.x <= 0.0f ||
			plan.finalOutputSize.y <= 0.0f ||
			plan.engineRenderSize.width <= 0.0f ||
			plan.engineRenderSize.height <= 0.0f) {
			return false;
		}

		const uint32_t displayWidth = ClampPositiveDimension(plan.finalOutputSize.x);
		const uint32_t displayHeight = ClampPositiveDimension(plan.finalOutputSize.y);
		const uint32_t renderWidth = ClampPositiveDimension(plan.engineRenderSize.width);
		const uint32_t renderHeight = ClampPositiveDimension(plan.engineRenderSize.height);
		if (!displayWidth ||
			!displayHeight ||
			!renderWidth ||
			!renderHeight ||
			(displayWidth & 1u) != 0 ||
			(renderWidth & 1u) != 0 ||
			displayWidth != ClampPositiveDimension(a_state->screenSize.x) ||
			displayHeight != ClampPositiveDimension(a_state->screenSize.y) ||
			a_colorWidth != displayWidth / 2u ||
			a_colorHeight != displayHeight ||
			a_depthWidth != renderWidth / 2u ||
			a_depthHeight != renderHeight) {
			return false;
		}

		winrt::com_ptr<ID3D11Resource> colorResource;
		winrt::com_ptr<ID3D11Resource> depthResource;
		a_colorUAV->GetResource(colorResource.put());
		a_depthSRV->GetResource(depthResource.put());
		if (!colorResource || !depthResource)
			return false;

		D3D11_TEXTURE2D_DESC colorDesc{};
		D3D11_TEXTURE2D_DESC depthDesc{};
		if (!TryGetTexture2DDesc(colorResource.get(), colorDesc) ||
			!TryGetTexture2DDesc(depthResource.get(), depthDesc) ||
			colorDesc.ArraySize != 1 ||
			colorDesc.MipLevels != 1 ||
			colorDesc.SampleDesc.Count != 1 ||
			depthDesc.ArraySize != 1 ||
			depthDesc.MipLevels != 1 ||
			depthDesc.SampleDesc.Count != 1) {
			return false;
		}

		const bool colorRegionValid =
			a_colorOffsetX <= colorDesc.Width &&
			a_colorWidth <= colorDesc.Width - a_colorOffsetX &&
			a_colorOffsetY <= colorDesc.Height &&
			a_colorHeight <= colorDesc.Height - a_colorOffsetY;
		const bool exactPerEyeColorLayout =
			colorDesc.Width == displayWidth / 2u &&
			a_colorOffsetX == 0;
		const bool exactCombinedColorLayout =
			colorDesc.Width == displayWidth &&
			a_colorOffsetX == a_eyeIndex * (displayWidth / 2u);
		if (!colorRegionValid ||
			colorDesc.Height != displayHeight ||
			(!exactPerEyeColorLayout && !exactCombinedColorLayout)) {
			return false;
		}

		auto* renderer = globals::game::renderer;
		if (!renderer)
			return false;
		for (const auto& output : a_upscaling.vrIntermediateColorOut) {
			if (!output || !output->resource || !output->uav)
				return false;
		}
		const auto colorIdentity = GetCOMIdentityAddress(colorResource.get());
		const auto& perEyeOutput = a_upscaling.vrIntermediateColorOut[a_eyeIndex];
		const bool perEyeOutputOwned =
			GetCOMIdentityAddress(perEyeOutput->resource.get()) == colorIdentity;
		const auto& mainTarget =
			renderer->GetRuntimeData().renderTargets[RE::RENDER_TARGETS::kMAIN];
		const bool combinedOutputOwned =
			(mainTarget.texture &&
				GetCOMIdentityAddress(mainTarget.texture) == colorIdentity) ||
			(a_upscaling.sharpenerTexture &&
				a_upscaling.sharpenerTexture->resource &&
				a_upscaling.sharpenerTexture->uav &&
				GetCOMIdentityAddress(a_upscaling.sharpenerTexture->resource.get()) == colorIdentity);
		if ((exactPerEyeColorLayout && !perEyeOutputOwned) ||
			(exactCombinedColorLayout && !combinedOutputOwned)) {
			return false;
		}

		auto& mainDepth =
			renderer->GetDepthStencilData().depthStencils[RE::RENDER_TARGETS_DEPTHSTENCIL::kMAIN];
		if (!mainDepth.texture ||
			!mainDepth.depthSRV ||
			a_depthSRV != mainDepth.depthSRV ||
			GetCOMIdentityAddress(depthResource.get()) !=
				GetCOMIdentityAddress(mainDepth.texture)) {
			return false;
		}

		const bool depthRegionValid =
			a_depthOffsetX <= depthDesc.Width &&
			a_depthWidth <= depthDesc.Width - a_depthOffsetX &&
			a_depthOffsetY <= depthDesc.Height &&
			a_depthHeight <= depthDesc.Height - a_depthOffsetY;
		const bool exactDepthLayout =
			(depthDesc.Width == displayWidth && depthDesc.Height == displayHeight) ||
			(depthDesc.Width == renderWidth && depthDesc.Height == renderHeight);
		return depthRegionValid &&
		       exactDepthLayout &&
		       a_depthOffsetX == a_eyeIndex * (renderWidth / 2u) &&
		       a_depthOffsetY == 0;
	}

	struct VRMenuPresentationTraceResourceInfo
	{
		std::uintptr_t identity = 0;
		int renderTargetIndex = -1;
		int depthStencilIndex = -1;
		bool textureCopy = false;
		D3D11_TEXTURE2D_DESC desc{};
		bool hasTextureDesc = false;
	};

	VRMenuPresentationTraceResourceInfo ResolveVRMenuPresentationTraceResource(ID3D11Resource* a_resource)
	{
		VRMenuPresentationTraceResourceInfo info{};
		if (!a_resource)
			return info;

		info.identity = GetCOMIdentityAddress(a_resource);
		info.hasTextureDesc = TryGetTexture2DDesc(a_resource, info.desc);
		auto* renderer = globals::game::renderer;
		if (!renderer)
			return info;

		winrt::com_ptr<ID3D11Texture2D> texture;
		if (FAILED(a_resource->QueryInterface(IID_PPV_ARGS(texture.put()))) || !texture)
			return info;

		const auto& renderTargets = renderer->GetRuntimeData().renderTargets;
		for (int targetIndex = 0; targetIndex < Util::GetRenderTargetCount(); ++targetIndex) {
			const auto& target = renderTargets[targetIndex];
			if (target.texture == texture.get() || target.textureCopy == texture.get()) {
				info.renderTargetIndex = targetIndex;
				info.textureCopy = target.textureCopy == texture.get();
				return info;
			}
		}

		const auto& depthStencils = renderer->GetDepthStencilData().depthStencils;
		for (int depthIndex = 0; depthIndex < Util::GetDepthStencilCount(); ++depthIndex) {
			if (depthStencils[depthIndex].texture == texture.get()) {
				info.depthStencilIndex = depthIndex;
				return info;
			}
		}

		return info;
	}

	std::string GetVRMenuPresentationTraceRenderTargetName(int a_targetIndex)
	{
		if (globals::game::isVR && a_targetIndex == RE::RENDER_TARGETS::kVR_FRAMEBUFFER)
			return "kVR_FRAMEBUFFER";

		const auto name = magic_enum::enum_name(static_cast<RE::RENDER_TARGETS::RENDER_TARGET>(a_targetIndex));
		return name.empty() ? std::format("rt#{}", a_targetIndex) : std::string(name);
	}

	std::string GetVRMenuPresentationTraceDepthTargetName(int a_depthIndex)
	{
		const auto name = magic_enum::enum_name(
			static_cast<RE::RENDER_TARGETS_DEPTHSTENCIL::RENDER_TARGET_DEPTHSTENCIL>(a_depthIndex));
		return name.empty() ? std::format("depth#{}", a_depthIndex) : std::string(name);
	}

	uint32_t GetVRMenuPresentationTraceFrame()
	{
		const auto* state = globals::state;
		return state ? std::max(state->frameCount, 1u) : 0u;
	}

	static_assert(std::size(kSkyrimPresentationMenuNames) + 4u <= 32u);
	constexpr uint32_t kVRMenuPresentationTraceMapBit = 1u << std::size(kSkyrimPresentationMenuNames);
	constexpr uint32_t kVRMenuPresentationTraceMainBit = kVRMenuPresentationTraceMapBit << 1u;
	constexpr uint32_t kVRMenuPresentationTraceLoadingBit = kVRMenuPresentationTraceMainBit << 1u;
	constexpr uint32_t kVRMenuPresentationTraceRaceSexPreRollBit = kVRMenuPresentationTraceLoadingBit << 1u;

	uint32_t GetVRMenuPresentationTraceMenuBit(std::string_view a_menuName)
	{
		for (uint32_t index = 0; index < std::size(kSkyrimPresentationMenuNames); ++index) {
			if (a_menuName == kSkyrimPresentationMenuNames[index])
				return 1u << index;
		}

		if (a_menuName == RE::MapMenu::MENU_NAME)
			return kVRMenuPresentationTraceMapBit;
		if (a_menuName == RE::MainMenu::MENU_NAME)
			return kVRMenuPresentationTraceMainBit;
		if (a_menuName == RE::LoadingMenu::MENU_NAME)
			return kVRMenuPresentationTraceLoadingBit;
		return 0;
	}

	uint32_t ReadVRMenuPresentationTraceMenuMask()
	{
		uint32_t mask = 0;
		auto* ui = globals::game::ui;
		if (ui) {
			for (uint32_t index = 0; index < std::size(kSkyrimPresentationMenuNames); ++index) {
				if (ui->IsMenuOpen(kSkyrimPresentationMenuNames[index]))
					mask |= 1u << index;
			}
			if (ui->IsMenuOpen(RE::MapMenu::MENU_NAME))
				mask |= kVRMenuPresentationTraceMapBit;
			if (ui->IsMenuOpen(RE::MainMenu::MENU_NAME))
				mask |= kVRMenuPresentationTraceMainBit;
			if (ui->IsMenuOpen(RE::LoadingMenu::MENU_NAME))
				mask |= kVRMenuPresentationTraceLoadingBit;
		}

		const auto* state = globals::state;
		if ((state && state->isMapMenuOpen) ||
			g_vrMapMenuOpenFromEvent.load(std::memory_order_acquire)) {
			mask |= kVRMenuPresentationTraceMapBit;
		}
		if (state && state->isMainMenuOpen)
			mask |= kVRMenuPresentationTraceMainBit;
		if ((state && state->isLoadingMenuOpen) ||
			g_vrLoadingMenuOpenFromEvent.load(std::memory_order_acquire)) {
			mask |= kVRMenuPresentationTraceLoadingBit;
		}
		if (g_vrRaceSexMenuOpenFromEvent.load(std::memory_order_acquire))
			mask |= GetVRMenuPresentationTraceMenuBit(RE::RaceSexMenu::MENU_NAME);
		if (g_vrMenuPresentationTraceRaceSexPreRollActive.load(std::memory_order_acquire))
			mask |= kVRMenuPresentationTraceRaceSexPreRollBit;
		return mask;
	}

	std::string DescribeVRMenuPresentationTraceMenuMask(uint32_t a_mask)
	{
		std::string description;
		auto append = [&](std::string_view a_name) {
			if (!description.empty())
				description += '|';
			description += a_name;
		};
		for (uint32_t index = 0; index < std::size(kSkyrimPresentationMenuNames); ++index) {
			if ((a_mask & (1u << index)) != 0)
				append(kSkyrimPresentationMenuNames[index]);
		}
		if ((a_mask & kVRMenuPresentationTraceMapBit) != 0)
			append(RE::MapMenu::MENU_NAME);
		if ((a_mask & kVRMenuPresentationTraceMainBit) != 0)
			append(RE::MainMenu::MENU_NAME);
		if ((a_mask & kVRMenuPresentationTraceLoadingBit) != 0)
			append(RE::LoadingMenu::MENU_NAME);
		if ((a_mask & kVRMenuPresentationTraceRaceSexPreRollBit) != 0)
			append("RaceSexPreRoll");
		return description.empty() ? "none" : description;
	}

	bool IsVRMenuPresentationTraceActive()
	{
		if (!kEnableVRMenuPresentationTraceDiagnostics ||
			!globals::game::isVR ||
			!g_vrMenuPresentationTraceDiagnosticsEnabled.load(std::memory_order_relaxed)) {
			return false;
		}

		return g_vrMenuPresentationTraceSession.load(std::memory_order_acquire) != 0 &&
		       g_vrMenuPresentationTraceMenuMask.load(std::memory_order_acquire) != 0;
	}

	bool IsVRMenuPresentationTraceMapActive()
	{
		return IsVRMenuPresentationTraceActive() &&
		       (g_vrMenuPresentationTraceMenuMask.load(std::memory_order_acquire) &
				   kVRMenuPresentationTraceMapBit) != 0;
	}

	void FlushVRMenuPresentationTraceLog() noexcept
	{
		try {
			if (const auto log = spdlog::default_logger())
				log->flush();
		} catch (...) {
		}
	}

