Upscaling::VRRenderScaleResourceKey Upscaling::BuildVRRenderScaleResourceKey(const VRRenderScaleProfileSnapshot& a_profile) const
{
	VRRenderScaleResourceKey key{};
	key.valid =
		a_profile.valid &&
		a_profile.displayEyeWidth != 0 &&
		a_profile.displayEyeHeight != 0 &&
		a_profile.renderEyeWidth != 0 &&
		a_profile.renderEyeHeight != 0;
	key.active = a_profile.active;
	key.method = a_profile.method;
	key.qualityMode = std::min(a_profile.qualityMode, kQualityModeMaxIndex);
	key.dlssPreset = ClampDLSSPresetUInt(a_profile.dlssPreset);
	key.displayEyeWidth = a_profile.displayEyeWidth;
	key.displayEyeHeight = a_profile.displayEyeHeight;
	key.renderEyeWidth = a_profile.renderEyeWidth;
	key.renderEyeHeight = a_profile.renderEyeHeight;
	key.contextCount = globals::game::isVR ? 2u : 1u;
	key.foveatedVendorDispatch = a_profile.active && IsFoveatedVendorDispatchEnabled(a_profile.method);
	key.peripheryTAA = key.foveatedVendorDispatch && IsPeripheryTAAEnabled(a_profile.method);

	if (!a_profile.active) {
		key.backend = VRRenderScaleBackendKind::None;
	} else if (a_profile.method == UpscaleMethod::kDLSS) {
		key.backend = VRRenderScaleBackendKind::DLSS;
	} else if (a_profile.method == UpscaleMethod::kFSR) {
		const bool runtimeFSR =
			!fidelityFX.IsRuntimeUpscalerFailureLatched() &&
			fidelityFX.ShouldUseRuntimeUpscalerForFSR();
		const bool runtimeFSR4 =
			runtimeFSR &&
			a_profile.fsr4RuntimeEnabled &&
			!fidelityFX.IsRuntimeFsr4FailureLatched() &&
			fidelityFX.IsRuntimeFsr4Available();
		key.backend = runtimeFSR4 ?
		                  VRRenderScaleBackendKind::FSR4Runtime :
		                  (runtimeFSR ? VRRenderScaleBackendKind::FSRRuntime : VRRenderScaleBackendKind::FSRHost);
	}
	return key;
}

Upscaling::VRRenderScaleResourceCompatibility Upscaling::CompareVRRenderScaleResourceKeys(
	const VRRenderScaleResourceKey& a_current,
	const VRRenderScaleResourceKey& a_target)
{
	VRRenderScaleResourceCompatibility compatibility{};
	auto recordChange = [&](VRRenderScaleResourceChange a_change) {
		compatibility.changeMask |= static_cast<uint32_t>(a_change);
	};

	if (!a_current.valid || !a_target.valid) {
		recordChange(VRRenderScaleResourceChange::RenderTargets);
		recordChange(VRRenderScaleResourceChange::VendorRuntime);
		recordChange(VRRenderScaleResourceChange::Presentation);
		recordChange(VRRenderScaleResourceChange::Options);
		return compatibility;
	}

	compatibility.canReuseRenderTargets =
		a_current.active == a_target.active &&
		a_current.displayEyeWidth == a_target.displayEyeWidth &&
		a_current.displayEyeHeight == a_target.displayEyeHeight &&
		a_current.renderEyeWidth == a_target.renderEyeWidth &&
		a_current.renderEyeHeight == a_target.renderEyeHeight;
	if (!compatibility.canReuseRenderTargets)
		recordChange(VRRenderScaleResourceChange::RenderTargets);

	compatibility.canReuseVendorRuntime =
		a_current.active &&
		a_target.active &&
		a_current.method == a_target.method &&
		a_current.backend == a_target.backend &&
		a_current.contextCount == a_target.contextCount &&
		a_current.displayEyeWidth == a_target.displayEyeWidth &&
		a_current.displayEyeHeight == a_target.displayEyeHeight &&
		a_current.renderEyeWidth == a_target.renderEyeWidth &&
		a_current.renderEyeHeight == a_target.renderEyeHeight;
	if (a_current.active != a_target.active ||
		a_current.method != a_target.method ||
		a_current.backend != a_target.backend ||
		a_current.contextCount != a_target.contextCount ||
		a_current.displayEyeWidth != a_target.displayEyeWidth ||
		a_current.displayEyeHeight != a_target.displayEyeHeight ||
		a_current.renderEyeWidth != a_target.renderEyeWidth ||
		a_current.renderEyeHeight != a_target.renderEyeHeight) {
		recordChange(VRRenderScaleResourceChange::VendorRuntime);
	}

	compatibility.canReusePresentation =
		compatibility.canReuseRenderTargets &&
		a_current.foveatedVendorDispatch == a_target.foveatedVendorDispatch &&
		a_current.peripheryTAA == a_target.peripheryTAA;
	if (!compatibility.canReusePresentation)
		recordChange(VRRenderScaleResourceChange::Presentation);

	const bool dlssOptionsRelevant =
		a_current.method == UpscaleMethod::kDLSS ||
		a_target.method == UpscaleMethod::kDLSS;
	if (a_current.qualityMode != a_target.qualityMode ||
		(dlssOptionsRelevant && a_current.dlssPreset != a_target.dlssPreset)) {
		recordChange(VRRenderScaleResourceChange::Options);
	}

	compatibility.exact =
		compatibility.changeMask == static_cast<uint32_t>(VRRenderScaleResourceChange::None);
	return compatibility;
}

uint64_t Upscaling::EstimateVRRenderScaleResourceBytes(const VRRenderScaleResourceKey& a_key)
{
	if (!a_key.valid)
		return 0;

	const uint64_t contextCount = std::max(a_key.contextCount, 1u);
	const uint64_t inputPixels =
		static_cast<uint64_t>(a_key.renderEyeWidth) * a_key.renderEyeHeight * contextCount;
	const uint64_t outputPixels =
		static_cast<uint64_t>(a_key.displayEyeWidth) * a_key.displayEyeHeight * contextCount;
	uint64_t estimatedBytes = inputPixels * 24u + outputPixels * 8u;
	if (!a_key.active)
		return estimatedBytes;

	switch (a_key.backend) {
	case VRRenderScaleBackendKind::DLSS:
		estimatedBytes += outputPixels * 8u + contextCount * 96u * kVRRenderScaleMiB;
		break;
	case VRRenderScaleBackendKind::FSRHost:
		// VR FSR submit inputs are held at maximum display bounds so their D3D
		// identities can survive render-scale quality relatches.
		estimatedBytes += outputPixels * 16u + outputPixels * 8u + contextCount * 64u * kVRRenderScaleMiB;
		break;
	case VRRenderScaleBackendKind::FSRRuntime:
	case VRRenderScaleBackendKind::FSR4Runtime:
		estimatedBytes += outputPixels * 24u + outputPixels * 16u + contextCount * 96u * kVRRenderScaleMiB;
		break;
	default:
		break;
	}

	if (a_key.foveatedVendorDispatch) {
		estimatedBytes += outputPixels * 8u;
		if (a_key.method == UpscaleMethod::kFSR)
			estimatedBytes += outputPixels * 16u;
	}
	if (a_key.peripheryTAA)
		estimatedBytes += inputPixels * 16u;
	return estimatedBytes;
}

bool Upscaling::RecordVRRenderScaleTransitionRequested(
	const VRRenderScaleDesiredProfile& a_request)
{
	const auto profile = BuildVRRenderScaleRequestProfile(*this, a_request);
	std::unique_lock queueLock(
		perfModeRenderTargetRecreateQueueMutex);
	std::unique_lock requestLock(
		pendingVRRenderScaleRequestMutex);
	if (!pendingVRRenderScaleRequest ||
		pendingVRRenderScaleRequest->requestID != a_request.requestID ||
		pendingVRRenderScaleRequest->transitionEpoch !=
			a_request.transitionEpoch ||
		latestVRRenderScaleRequestID.load(
			std::memory_order_acquire) != a_request.requestID) {
		// A newer latest-wins request published before this controller write.
		// Dropping the stale recorder preserves the newer pending/controller order.
		return false;
	}
	if (!IsVRRenderScaleRecoveryOrigin(a_request.origin) &&
		(vrRenderScaleUnresolvedPhysicalMutationEpoch.load(
			 std::memory_order_acquire) != 0 ||
			vrRenderScalePostMutationSerializationEpoch.load(
				std::memory_order_acquire) != 0 ||
			vrRenderScalePreMutationNativeFallbackAdmissionActive.load(
				std::memory_order_acquire) ||
			HasLiveVRRenderScaleProviderNeutralRecoveryWorker())) {
		if (pendingVRRenderScaleRequest &&
			pendingVRRenderScaleRequest->requestID == a_request.requestID &&
			pendingVRRenderScaleRequest->transitionEpoch ==
				a_request.transitionEpoch) {
			pendingVRRenderScaleRequest.reset();
		}
		(void)StoreDeferredVRRenderScaleRequestLatestWinsLocked(a_request);
		return false;
	}
	uint64_t guardEpoch =
		vrNativeRestorePresentationGuardEpoch.load(
			std::memory_order_acquire);
	if (guardEpoch != 0 && guardEpoch != profile.transitionEpoch) {
		const auto nativeRestoreProgress =
			GetVRLowPeakNativeRestoreProgress();
		if (VRVendorRelatchPolicy::HasNativeRestoreTransaction(
				nativeRestoreProgress)) {
			// Queue serialization prevents OpenVR from observing this exchange until
			// the controller target below owns the same successor epoch.
			ArmVRNativeRestorePresentationGuard(profile.transitionEpoch);
		} else if (vrNativeRestorePresentationGuardEpoch.compare_exchange_strong(
					   guardEpoch,
					   0,
					   std::memory_order_acq_rel,
					   std::memory_order_acquire)) {
			ClearVRNativeRestorePresentationWatchdog();
		}
	}
	const auto currentProfile = BuildCurrentVRRenderScaleProfile(*this);
	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : a_request.queuedFrame;
	VRRenderScaleTransitionState previousState;
	uint64_t revision;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		previousState = vrRenderScaleTransitionController.state;
		if (!vrRenderScaleTransitionController.stable.valid) {
			vrRenderScaleTransitionController.stable =
				vrRenderScaleTransitionController.applied.valid ?
					vrRenderScaleTransitionController.applied :
					currentProfile;
		}
		vrRenderScaleTransitionController.requested = profile;
		vrRenderScaleTransitionController.targetEpoch = profile.transitionEpoch;
		vrRenderScaleTransitionController.relatchPlan = {};
		StoreVRRenderScaleTransitionStateLocked(VRRenderScaleTransitionState::Requested);
		vrRenderScaleStableRuntimeProfileAuthoritative.store(true, std::memory_order_release);
		vrRenderScaleTransitionController.transitionStartEpoch =
			profile.transitionEpoch;
		vrRenderScaleTransitionController.transitionStartFrame = frame;
		vrRenderScaleTransitionController.stateFrame = frame;
		if (vrRenderScaleTransitionController.metrics.current.valid)
			ArchiveVRRenderScaleTransitionMetricsLocked(false, true, frame);
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		metrics = {};
		metrics.valid = true;
		metrics.transitionEpoch = profile.transitionEpoch;
		metrics.requestID = profile.requestID;
		metrics.contractGeneration = profile.contractGeneration;
		metrics.origin = profile.origin;
		metrics.method = profile.method;
		metrics.resources = profile.resources;
		metrics.requestedFrame = frame;
		metrics.peakPressure = vrRenderScaleTransitionController.memory.pressure;
		metrics.peakUsageBytes = vrRenderScaleTransitionController.memory.currentUsageBytes;
		metrics.peakSystemCommitBytes = vrRenderScaleTransitionController.memory.systemCommitBytes;
		metrics.peakProcessPrivateUsageBytes = vrRenderScaleTransitionController.memory.processPrivateUsageBytes;
		metrics.peakRetiredSets = vrRenderScaleTransitionController.retirement.pendingSets;
		revision = ++vrRenderScaleTransitionController.revision;
	}
	// The exact-owner transaction ends with coherent controller publication.
	// Diagnostics recursively snapshot the pending request and vendor gate, so
	// they must run after both non-recursive ownership locks have been released.
	requestLock.unlock();
	queueLock.unlock();
	if (ShouldEmitUpscalingDiagLogs()) {
		logger::debug(
			"[VRRenderScale][Controller] revision={} {} -> Requested request={} epoch={} method={} quality={} active={} frame={}",
			revision,
			GetVRRenderScaleTransitionStateName(previousState),
			profile.requestID,
			profile.transitionEpoch,
			magic_enum::enum_name(profile.method),
			profile.qualityMode,
			BoolText(profile.active),
			frame);
	}
	RecordVRRenderScaleStressEvent(VRRenderScaleStressEventType::Request);
	return true;
}

uint64_t Upscaling::AllocateVRRenderScaleTransitionEpoch()
{
	uint64_t epoch = nextVRRenderScaleTransitionEpoch.fetch_add(1, std::memory_order_acq_rel);
	if (epoch == 0)
		epoch = nextVRRenderScaleTransitionEpoch.fetch_add(1, std::memory_order_acq_rel);
	return epoch;
}

void Upscaling::BindVRRenderScaleRelatchEpoch(uint64_t a_epoch)
{
	if (a_epoch == 0)
		return;

	const uint32_t frame =
		globals::state ?
			std::max(globals::state->frameCount, 1u) :
			0u;
	auto desiredProfile = GetPendingVRRenderScaleDesiredProfile();
	desiredProfile.transitionEpoch = a_epoch;
	desiredProfile.queuedFrame = frame;
	const auto boundProfile =
		BuildVRRenderScaleRequestProfile(*this, desiredProfile);
	std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
	const bool settled =
		vrRenderScaleTransitionController.state == VRRenderScaleTransitionState::Idle ||
		vrRenderScaleTransitionController.state == VRRenderScaleTransitionState::Active;
	if (settled || vrRenderScaleTransitionController.targetEpoch == 0) {
		if (vrRenderScaleTransitionController.metrics.current.valid &&
			vrRenderScaleTransitionController.metrics.current.transitionEpoch != a_epoch) {
			ArchiveVRRenderScaleTransitionMetricsLocked(false, true, frame);
		}
		vrRenderScaleTransitionController.targetEpoch = a_epoch;
		if (!vrRenderScaleTransitionController.requested.valid ||
			vrRenderScaleTransitionController.requested.transitionEpoch !=
				a_epoch) {
			vrRenderScaleTransitionController.requested = boundProfile;
		}
		vrRenderScaleTransitionController.relatchPlan = {};
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		if (!metrics.valid) {
			metrics.valid = true;
			metrics.transitionEpoch = a_epoch;
			metrics.requestedFrame = frame;
			metrics.peakPressure = vrRenderScaleTransitionController.memory.pressure;
			metrics.peakUsageBytes = vrRenderScaleTransitionController.memory.currentUsageBytes;
			metrics.peakSystemCommitBytes = vrRenderScaleTransitionController.memory.systemCommitBytes;
			metrics.peakProcessPrivateUsageBytes = vrRenderScaleTransitionController.memory.processPrivateUsageBytes;
			metrics.peakRetiredSets = vrRenderScaleTransitionController.retirement.pendingSets;
		}
		++vrRenderScaleTransitionController.revision;
	}
}

bool Upscaling::IsVRRenderScaleTransitionEpochCurrent(uint64_t a_epoch) const
{
	if (a_epoch == 0)
		return true;

	std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
	return vrRenderScaleTransitionController.targetEpoch == a_epoch;
}

bool Upscaling::RecordVRRenderScaleRelatchPlan(const VRRenderScaleRelatchPlan& a_plan)
{
	if (!a_plan.valid || a_plan.transitionEpoch == 0)
		return false;

	uint64_t revision;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		if (vrRenderScaleTransitionController.targetEpoch != a_plan.transitionEpoch)
			return false;

		vrRenderScaleTransitionController.relatchPlan = a_plan;
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		if (metrics.valid && metrics.transitionEpoch == a_plan.transitionEpoch) {
			metrics.contractGeneration = a_plan.contractGeneration;
			metrics.origin = a_plan.origin;
			metrics.method = a_plan.target.method;
			metrics.resources = a_plan.target;
			if (static_cast<uint32_t>(a_plan.memoryPressure) > static_cast<uint32_t>(metrics.peakPressure))
				metrics.peakPressure = a_plan.memoryPressure;
		}
		revision = ++vrRenderScaleTransitionController.revision;
	}
	if (ShouldEmitUpscalingDiagLogs()) {
		logger::debug(
			"[VRRenderScale][Plan] revision={} epoch={} generation={} actions=0x{:X} changes=0x{:X} previousVendor={} backend={} -> {} reuseTargets={} reuseStableTargets={} dimensionsMatch={} stableEvidence={} vendorDimensionsUnchanged={} reuseShared={} preserveDLSS={} preserveFSR={} compatibleFSRReuse={} preserveFSRIntermediates={} retainWarmDLSS={} retainWarmFSR={} reuseWarmTarget={} recreateFSR={} waitFSRDrain={} lowPeakRestore={} pressure={} current={} MiB target={} MiB additional={} MiB projectedAdditional={} MiB projectedUsage={} MiB admissionLimit={} MiB postTrimAdmissionLimit={} MiB projectedSystemAdditional={} MiB projectedSystemCommit={} MiB systemAdmissionLimit={} MiB cleanup={} projectedGuard={} postTrimRelaxed={} projectedDeferred={} systemGuard={} doorHardReserveOnly={} systemDeferred={} deferred={} emergencyCommitGuard={} emergencyMultiplier={} emergencyMinimumProjection={} MiB emergencyProjectionValid={} emergencyProjectedAdditional={} MiB emergencyProjectedCommit={} MiB emergencyAdmissionLimit={} MiB emergencyReserve={} MiB emergencySafe={}",
			revision,
			a_plan.transitionEpoch,
			a_plan.contractGeneration,
			a_plan.actionMask,
			a_plan.compatibility.changeMask,
			magic_enum::enum_name(a_plan.previousVendorMethod),
			magic_enum::enum_name(a_plan.current.backend),
			magic_enum::enum_name(a_plan.target.backend),
			BoolText(a_plan.reuseRenderTargets),
			BoolText(a_plan.reuseStableRenderTargets),
			BoolText(a_plan.renderTargetDimensionsMatch),
			BoolText(a_plan.stableContractEvidenceMatches),
			BoolText(a_plan.vendorDimensionsUnchanged),
			BoolText(a_plan.reuseSharedSubmitResources),
			BoolText(a_plan.preserveDLSSResources),
			BoolText(a_plan.preserveFSRResources),
			BoolText(a_plan.reuseCompatibleFSRResources),
			BoolText(a_plan.preserveCompatibleFSRIntermediates),
			BoolText(a_plan.retainWarmDLSSResources),
			BoolText(a_plan.retainWarmFSRResources),
			BoolText(a_plan.reuseWarmTargetRuntime),
			BoolText(a_plan.recreateFSRResources),
			BoolText(a_plan.waitForFSRDrain),
			BoolText(a_plan.lowPeakNativeRestore),
			GetVRRenderScaleMemoryPressureName(a_plan.memoryPressure),
			a_plan.estimatedCurrentBytes / kVRRenderScaleMiB,
			a_plan.estimatedTargetBytes / kVRRenderScaleMiB,
			a_plan.estimatedAdditionalBytes / kVRRenderScaleMiB,
			a_plan.projectedAdditionalBytes / kVRRenderScaleMiB,
			a_plan.projectedUsageBytes / kVRRenderScaleMiB,
			a_plan.admissionUsageLimitBytes / kVRRenderScaleMiB,
			a_plan.postTrimAdmissionUsageLimitBytes / kVRRenderScaleMiB,
			a_plan.projectedSystemCommitAdditionalBytes / kVRRenderScaleMiB,
			a_plan.projectedSystemCommitBytes / kVRRenderScaleMiB,
			a_plan.systemCommitAdmissionLimitBytes / kVRRenderScaleMiB,
			BoolText(a_plan.pressureCleanupRequired),
			BoolText(a_plan.projectedResidencyGuardActive),
			BoolText(a_plan.projectedResidencyPostTrimRelaxed),
			BoolText(a_plan.projectedResidencyDeferred),
			BoolText(a_plan.systemCommitGuardActive),
			BoolText(a_plan.doorHandoffHardReserveOnly),
			BoolText(a_plan.systemCommitDeferred),
			BoolText(a_plan.pressureDeferred),
			BoolText(a_plan.emergencySystemCommitGuardActive),
			a_plan.emergencySystemCommitProjectionMultiplier,
			a_plan.emergencySystemCommitMinimumProjectionBytes / kVRRenderScaleMiB,
			BoolText(a_plan.emergencySystemCommitProjectionValid),
			a_plan.emergencyProjectedSystemCommitAdditionalBytes / kVRRenderScaleMiB,
			a_plan.emergencyProjectedSystemCommitBytes / kVRRenderScaleMiB,
			a_plan.emergencySystemCommitAdmissionLimitBytes / kVRRenderScaleMiB,
			a_plan.emergencySystemCommitReserveBytes / kVRRenderScaleMiB,
			BoolText(a_plan.emergencySystemCommitSafe));
	}
	return true;
}

bool Upscaling::RecordVRRenderScaleTransitionPreparing(const VRRenderScaleDesiredProfile& a_request)
{
	const auto profile = BuildVRRenderScaleRequestProfile(*this, a_request);
	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : a_request.queuedFrame;
	VRRenderScaleTransitionState previousState;
	uint64_t revision;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		if (vrRenderScaleTransitionController.targetEpoch != profile.transitionEpoch)
			return false;

		previousState = vrRenderScaleTransitionController.state;
		vrRenderScaleTransitionController.applying = profile;
		StoreVRRenderScaleTransitionStateLocked(VRRenderScaleTransitionState::Preparing);
		vrRenderScaleStableRuntimeProfileAuthoritative.store(false, std::memory_order_release);
		vrRenderScaleTransitionController.stateFrame = frame;
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		if (metrics.valid && metrics.transitionEpoch == profile.transitionEpoch)
			metrics.preparingFrame = metrics.preparingFrame != 0 ? metrics.preparingFrame : frame;
		revision = ++vrRenderScaleTransitionController.revision;
	}

	if (ShouldEmitUpscalingDiagLogs()) {
		logger::debug(
			"[VRRenderScale][Controller] revision={} {} -> Preparing request={} epoch={} frame={} reason=request snapshot consumed",
			revision,
			GetVRRenderScaleTransitionStateName(previousState),
			profile.requestID,
			profile.transitionEpoch,
			frame);
	}
	return true;
}

void Upscaling::StoreVRRenderScaleTransitionStateLocked(VRRenderScaleTransitionState a_state) noexcept
{
	vrRenderScaleTransitionController.state = a_state;
	vrRenderScaleTransitionState.store(a_state, std::memory_order_release);
}

void Upscaling::SetVRRenderScaleTransitionState(VRRenderScaleTransitionState a_state, const char* a_reason)
{
	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : 0u;
	VRRenderScaleTransitionState previousState;
	uint64_t revision = 0;
	uint64_t requestID = 0;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		previousState = vrRenderScaleTransitionController.state;
		if (previousState == a_state)
			return;

		StoreVRRenderScaleTransitionStateLocked(a_state);
		vrRenderScaleStableRuntimeProfileAuthoritative.store(
			a_state == VRRenderScaleTransitionState::Requested ||
				a_state == VRRenderScaleTransitionState::WaitingForSafePoint,
			std::memory_order_release);
		vrRenderScaleTransitionController.stateFrame = frame;
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		if (metrics.valid) {
			if (a_state == VRRenderScaleTransitionState::Preparing && metrics.preparingFrame == 0)
				metrics.preparingFrame = frame;
			if (a_state == VRRenderScaleTransitionState::Applying && metrics.applyingFrame == 0)
				metrics.applyingFrame = frame;
		}
		revision = ++vrRenderScaleTransitionController.revision;
		requestID = vrRenderScaleTransitionController.applying.valid ?
		                vrRenderScaleTransitionController.applying.requestID :
		                vrRenderScaleTransitionController.requested.requestID;
	}

	if (ShouldEmitUpscalingDiagLogs()) {
		logger::debug(
			"[VRRenderScale][Controller] revision={} {} -> {} request={} frame={}{}{}",
			revision,
			GetVRRenderScaleTransitionStateName(previousState),
			GetVRRenderScaleTransitionStateName(a_state),
			requestID,
			frame,
			a_reason && *a_reason ? " reason=" : "",
			a_reason && *a_reason ? a_reason : "");
	}
}

bool Upscaling::PublishVRRenderScaleTransitionApplied(VRUpscalingTransitionOrigin a_origin, bool a_requiresStabilization, uint64_t a_epoch)
{
	VRRenderScaleProfileSnapshot source{};
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		if (vrRenderScaleTransitionController.applying.valid &&
			(a_epoch == 0 || vrRenderScaleTransitionController.applying.transitionEpoch == a_epoch)) {
			source = vrRenderScaleTransitionController.applying;
		} else if (vrRenderScaleTransitionController.requested.valid &&
				   (a_epoch == 0 || vrRenderScaleTransitionController.requested.transitionEpoch == a_epoch)) {
			source = vrRenderScaleTransitionController.requested;
		}
	}
	if (!source.valid)
		return false;

	source.transitionEpoch = a_epoch != 0 ? a_epoch : source.transitionEpoch;
	const auto appliedProfile = BuildVRRenderScaleAppliedProfile(*this, source, a_origin);
	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : 0u;
	VRRenderScaleTransitionState previousState;
	VRRenderScaleTransitionState nextState;
	bool completedSynchronously = false;
	uint64_t revision;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		const bool sourceStillOwned =
			(vrRenderScaleTransitionController.applying.valid &&
				vrRenderScaleTransitionController.applying.requestID == source.requestID &&
				vrRenderScaleTransitionController.applying.transitionEpoch == source.transitionEpoch) ||
			(vrRenderScaleTransitionController.requested.valid &&
				vrRenderScaleTransitionController.requested.requestID == source.requestID &&
				vrRenderScaleTransitionController.requested.transitionEpoch == source.transitionEpoch);
		if (!sourceStillOwned ||
			(a_epoch != 0 &&
				vrRenderScaleTransitionController.targetEpoch != a_epoch)) {
			return false;
		}

		previousState = vrRenderScaleTransitionController.state;
		vrRenderScaleTransitionController.applied = appliedProfile;
		vrRenderScaleTransitionController.applying = {};
		auto& fidelity = vrRenderScaleTransitionController.fidelity;
		fidelity = {};
		fidelity.active = appliedProfile.active && IsVendorUpscalingMethod(appliedProfile.method);
		fidelity.transitionEpoch = appliedProfile.transitionEpoch;
		fidelity.contractGeneration = appliedProfile.contractGeneration;
		fidelity.method = appliedProfile.method;
		fidelity.backend = appliedProfile.resources.backend;
		fidelity.expectedInputWidth = appliedProfile.renderEyeWidth;
		fidelity.expectedInputHeight = appliedProfile.renderEyeHeight;
		fidelity.expectedOutputWidth = appliedProfile.displayEyeWidth;
		fidelity.expectedOutputHeight = appliedProfile.displayEyeHeight;
		const bool newerRequestPending =
			vrRenderScaleTransitionController.targetEpoch != 0 &&
			appliedProfile.transitionEpoch != 0 &&
			vrRenderScaleTransitionController.targetEpoch != appliedProfile.transitionEpoch;
		completedSynchronously = !a_requiresStabilization && !newerRequestPending;
		if (newerRequestPending) {
			if (!a_requiresStabilization)
				vrRenderScaleTransitionController.stable = appliedProfile;
			nextState = VRRenderScaleTransitionState::Requested;
		} else if (a_requiresStabilization) {
			nextState = VRRenderScaleTransitionState::Stabilizing;
		} else {
			vrRenderScaleTransitionController.stable = appliedProfile;
			nextState = VRRenderScaleTransitionState::Active;
		}
		StoreVRRenderScaleTransitionStateLocked(nextState);
		vrRenderScaleStableRuntimeProfileAuthoritative.store(
			nextState == VRRenderScaleTransitionState::Requested ||
				nextState == VRRenderScaleTransitionState::WaitingForSafePoint,
			std::memory_order_release);
		vrRenderScaleTransitionController.stateFrame = frame;
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		if (metrics.valid && metrics.transitionEpoch == appliedProfile.transitionEpoch) {
			metrics.appliedFrame = frame;
			metrics.contractGeneration = appliedProfile.contractGeneration;
			metrics.origin = appliedProfile.origin;
			metrics.method = appliedProfile.method;
			metrics.resources = appliedProfile.resources;
			if (completedSynchronously) {
				metrics.stableFrame = frame;
				ArchiveVRRenderScaleTransitionMetricsLocked(true, false, frame);
			}
		}
		revision = ++vrRenderScaleTransitionController.revision;
	}

	if (ShouldEmitUpscalingDiagLogs()) {
		logger::debug(
			"[VRRenderScale][Controller] revision={} {} -> {} request={} epoch={} generation={} method={} active={} render={}x{} display={}x{}",
			revision,
			GetVRRenderScaleTransitionStateName(previousState),
			GetVRRenderScaleTransitionStateName(nextState),
			appliedProfile.requestID,
			appliedProfile.transitionEpoch,
			appliedProfile.contractGeneration,
			magic_enum::enum_name(appliedProfile.method),
			BoolText(appliedProfile.active),
			appliedProfile.renderEyeWidth,
			appliedProfile.renderEyeHeight,
			appliedProfile.displayEyeWidth,
			appliedProfile.displayEyeHeight);
	}
	if (a_origin != VRUpscalingTransitionOrigin::PostLoadSync)
		SampleVRRenderScaleMemory(true, "contract applied");
	RecordVRRenderScaleStressEvent(VRRenderScaleStressEventType::Applied);
	if (completedSynchronously)
		RecordVRRenderScaleStressEvent(VRRenderScaleStressEventType::Stable);
	return true;
}

bool Upscaling::PublishVRRenderScaleTransitionStable(
	uint64_t a_expectedEpoch,
	uint32_t a_expectedGeneration,
	UpscaleMethod a_expectedMethod,
	bool a_compositorHoldLockOwned)
{
	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : 0u;
	VRRenderScaleProfileSnapshot stableProfile{};
	VRRenderScaleTransitionState previousState;
	VRRenderScaleTransitionState nextState;
	uint64_t revision;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		const auto& applied = vrRenderScaleTransitionController.applied;
		if (vrRenderScaleTransitionController.state !=
				VRRenderScaleTransitionState::Stabilizing ||
			!applied.valid ||
			applied.transitionEpoch != a_expectedEpoch ||
			applied.contractGeneration != a_expectedGeneration ||
			applied.method != a_expectedMethod ||
			(vrRenderScaleTransitionController.targetEpoch != 0 &&
				vrRenderScaleTransitionController.targetEpoch !=
					a_expectedEpoch)) {
			return false;
		}
		previousState = vrRenderScaleTransitionController.state;
		stableProfile = BuildVRRenderScaleAppliedProfile(
			*this,
			applied,
			applied.origin);
		vrRenderScaleTransitionController.stable = stableProfile;
		const bool newerTargetPending =
			vrRenderScaleTransitionController.targetEpoch != 0 &&
			stableProfile.transitionEpoch != 0 &&
			vrRenderScaleTransitionController.targetEpoch != stableProfile.transitionEpoch;
		nextState = newerTargetPending ?
		                VRRenderScaleTransitionState::Requested :
		                VRRenderScaleTransitionState::Active;
		StoreVRRenderScaleTransitionStateLocked(nextState);
		vrRenderScaleStableRuntimeProfileAuthoritative.store(
			nextState == VRRenderScaleTransitionState::Requested ||
				nextState == VRRenderScaleTransitionState::WaitingForSafePoint,
			std::memory_order_release);
		vrRenderScaleTransitionController.stateFrame = frame;
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		if (metrics.valid && metrics.transitionEpoch == stableProfile.transitionEpoch) {
			metrics.stableFrame = frame;
			ArchiveVRRenderScaleTransitionMetricsLocked(true, false, frame);
		}
		revision = ++vrRenderScaleTransitionController.revision;
	}

	if (ShouldEmitUpscalingDiagLogs()) {
		logger::debug(
			"[VRRenderScale][Controller] revision={} {} -> {} stableRequest={} epoch={} generation={} frame={}",
			revision,
			GetVRRenderScaleTransitionStateName(previousState),
			GetVRRenderScaleTransitionStateName(nextState),
			stableProfile.requestID,
			stableProfile.transitionEpoch,
			stableProfile.contractGeneration,
			frame);
	}
	RecordVRRenderScaleStressEvent(VRRenderScaleStressEventType::Stable);
	if (nextState == VRRenderScaleTransitionState::Active) {
		if (a_compositorHoldLockOwned) {
			const std::scoped_lock physicalLock(
				vrRenderScalePhysicalMutationMutex);
			(void)TryRetireVRRenderScalePostMutationSerializationLocked(
				a_expectedEpoch);
		} else {
			(void)TryRetireVRRenderScalePostMutationSerialization(
				a_expectedEpoch);
		}
	}
	return true;
}

void Upscaling::ResetVRRenderScaleTransitionController(const char* a_reason)
{
	const std::scoped_lock queueLock(
		perfModeRenderTargetRecreateQueueMutex);
	fsrResourceFailureRequestKey.reset();
	vrNativeRestorePresentationGuardEpoch.store(
		0,
		std::memory_order_release);
	ClearAllVRLowPeakNativeRestoreProgress();
	ClearAllVRFpsStabilizerAPITransitionProfileAdmissions();
	ClearVRNativeRestorePresentationWatchdog();
	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : 0u;
	vrRenderScaleMemoryTrimFence = nullptr;
	vrRenderScaleMemoryTrimOwnerEpoch = 0;
	vrRenderScaleMemoryTrimPendingReason = VRRenderScaleMemoryTrimReason::None;
	vrRenderScaleMemoryTrimRequestedFrame = 0;
	vrRenderScaleMemoryTrimFenceFailures = 0;
	VRRenderScaleTransitionState previousState;
	uint64_t revision;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		previousState = vrRenderScaleTransitionController.state;
		revision = vrRenderScaleTransitionController.revision + 1u;
		if (vrRenderScaleTransitionController.metrics.current.valid)
			ArchiveVRRenderScaleTransitionMetricsLocked(false, true, frame);
		const auto retirement = vrRenderScaleTransitionController.retirement;
		const auto engineTargetRetirement = vrRenderScaleTransitionController.engineTargetRetirement;
		const auto dlssLifecycle = vrRenderScaleTransitionController.dlssLifecycle;
		const auto fsrLifecycle = vrRenderScaleTransitionController.fsrLifecycle;
		const auto metrics = vrRenderScaleTransitionController.metrics;
		const auto presentation = vrRenderScaleTransitionController.presentation;
		vrRenderScaleTransitionController = {};
		StoreVRRenderScaleTransitionStateLocked(VRRenderScaleTransitionState::Idle);
		vrRenderScaleStableRuntimeProfileAuthoritative.store(false, std::memory_order_release);
		vrRenderScaleTransitionController.revision = revision;
		vrRenderScaleTransitionController.retirement = retirement;
		vrRenderScaleTransitionController.engineTargetRetirement = engineTargetRetirement;
		vrRenderScaleTransitionController.dlssLifecycle = dlssLifecycle;
		vrRenderScaleTransitionController.fsrLifecycle = fsrLifecycle;
		vrRenderScaleTransitionController.metrics = metrics;
		vrRenderScaleTransitionController.presentation = presentation;
	}

	if (ShouldEmitUpscalingDiagLogs() && previousState != VRRenderScaleTransitionState::Idle) {
		logger::debug(
			"[VRRenderScale][Controller] revision={} {} -> Idle{}{}",
			revision,
			GetVRRenderScaleTransitionStateName(previousState),
			a_reason && *a_reason ? " reason=" : "",
			a_reason && *a_reason ? a_reason : "");
	}
}

uint32_t Upscaling::GetActiveVRRenderScaleContractGeneration() const
{
	const auto& boot = perfMode.GetBootSnapshot();
	return IsVRRenderScaleModeLatched() && boot.valid ? boot.generation : 0u;
}

bool Upscaling::IsVendorRuntimeReadyForActiveContract(UpscaleMethod a_upscaleMethod) const
{
	if (!globals::game::isVR || !IsVRRenderScaleModeLatched())
		return true;

	const uint32_t generation = GetActiveVRRenderScaleContractGeneration();
	if (generation == 0)
		return false;

	switch (a_upscaleMethod) {
	case UpscaleMethod::kDLSS:
		return !pendingDLSSReset.load(std::memory_order_acquire) &&
		       vrDLSSRuntimeResourceGeneration == generation;
	case UpscaleMethod::kFSR:
		return !pendingFSRReset.load(std::memory_order_acquire) &&
		       vrFSRRuntimeResourceGeneration == generation &&
		       fidelityFX.HasFSRResources();
	default:
		return true;
	}
}

void Upscaling::MarkVendorRuntimeResourcesDirty(UpscaleMethod a_upscaleMethod, uint32_t a_generation)
{
	const uint32_t generation = a_generation != 0 ? a_generation : GetActiveVRRenderScaleContractGeneration();
	switch (a_upscaleMethod) {
	// Hot-Envelope: these two flags are what stranded the whole renderer when the
	// relatch was skipped - GetVRUpscalingApplyBlockReasonsForAPI folds them into
	// RelatchPending, which refuses the external API AND the CS menu alike. The
	// existing lifecycle record is logger::debug behind ShouldEmitUpscalingDiagLogs,
	// so a stranded flag left no trace. Log the edges at info, deduplicated by the
	// flag's own transition so this costs one line per real change.
	case UpscaleMethod::kDLSS:
		pendingDLSSResetGeneration.store(generation, std::memory_order_release);
		if (!pendingDLSSReset.exchange(true, std::memory_order_acq_rel)) {
			logger::info("[HotEnvelope][vendor] DLSS resources DIRTY at generation {}. Requests are refused until a matching READY.", generation);
		}
		break;
	case UpscaleMethod::kFSR:
		pendingFSRResetGeneration.store(generation, std::memory_order_release);
		if (!pendingFSRReset.exchange(true, std::memory_order_acq_rel)) {
			logger::info("[HotEnvelope][vendor] FSR resources DIRTY at generation {}. Requests are refused until a matching READY.", generation);
		}
		break;
	default:
		break;
	}
	RecordVRVendorRuntimeLifecycle(a_upscaleMethod, VRVendorRuntimeLifecyclePhase::Dirty, generation, "resources dirty");
}

void Upscaling::MarkVendorRuntimeResourcesReady(UpscaleMethod a_upscaleMethod, uint32_t a_generation)
{
	const uint32_t generation = a_generation != 0 ? a_generation : GetActiveVRRenderScaleContractGeneration();
	switch (a_upscaleMethod) {
	case UpscaleMethod::kDLSS:
		vrDLSSRuntimeResourceGeneration = generation;
		pendingDLSSResetGeneration.store(0, std::memory_order_release);
		if (pendingDLSSReset.exchange(false, std::memory_order_acq_rel)) {
			logger::info("[HotEnvelope][vendor] DLSS resources READY at generation {}.", generation);
		}
		break;
	case UpscaleMethod::kFSR:
		vrFSRRuntimeResourceGeneration = generation;
		pendingFSRResetGeneration.store(0, std::memory_order_release);
		if (pendingFSRReset.exchange(false, std::memory_order_acq_rel)) {
			logger::info("[HotEnvelope][vendor] FSR resources READY at generation {}.", generation);
		}
		break;
	default:
		break;
	}
	RecordVRVendorRuntimeLifecycle(a_upscaleMethod, VRVendorRuntimeLifecyclePhase::Ready, generation, "resources ready");
}

void Upscaling::ClearVendorRuntimeResourcesDirty(UpscaleMethod a_upscaleMethod, bool a_clearRuntimeGeneration)
{
	switch (a_upscaleMethod) {
	case UpscaleMethod::kDLSS:
		if (a_clearRuntimeGeneration)
			vrDLSSRuntimeResourceGeneration = 0;
		pendingDLSSResetGeneration.store(0, std::memory_order_release);
		// Distinct from READY: this drops the dirty flag without the resources
		// having been rebuilt. Worth telling apart in the log.
		if (pendingDLSSReset.exchange(false, std::memory_order_acq_rel)) {
			logger::info("[HotEnvelope][vendor] DLSS dirty flag CLEARED without rebuild (clearRuntimeGeneration={}).", a_clearRuntimeGeneration);
		}
		break;
	case UpscaleMethod::kFSR:
		if (a_clearRuntimeGeneration)
			vrFSRRuntimeResourceGeneration = 0;
		pendingFSRResetGeneration.store(0, std::memory_order_release);
		pendingFSRReset.store(false, std::memory_order_release);
		break;
	default:
		break;
	}
	const uint32_t runtimeGeneration =
		a_upscaleMethod == UpscaleMethod::kDLSS ? vrDLSSRuntimeResourceGeneration :
		a_upscaleMethod == UpscaleMethod::kFSR  ? vrFSRRuntimeResourceGeneration :
												  0u;
	const bool resourcesPresent =
		a_upscaleMethod == UpscaleMethod::kFSR ? fidelityFX.HasFSRResources() : runtimeGeneration != 0;
	RecordVRVendorRuntimeLifecycle(
		a_upscaleMethod,
		a_clearRuntimeGeneration || !resourcesPresent ?
			VRVendorRuntimeLifecyclePhase::Inactive :
			VRVendorRuntimeLifecyclePhase::Ready,
		runtimeGeneration,
		"resources cleared");
}

void Upscaling::RecordVRVendorRuntimeLifecycle(UpscaleMethod a_upscaleMethod, VRVendorRuntimeLifecyclePhase a_phase, uint32_t a_generation, const char* a_reason)
{
	if (a_upscaleMethod != UpscaleMethod::kDLSS && a_upscaleMethod != UpscaleMethod::kFSR)
		return;

	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : 0u;
	const uint32_t runtimeGeneration =
		a_upscaleMethod == UpscaleMethod::kDLSS ? vrDLSSRuntimeResourceGeneration : vrFSRRuntimeResourceGeneration;
	const bool resourcesPresent =
		a_upscaleMethod == UpscaleMethod::kFSR ? fidelityFX.HasFSRResources() : runtimeGeneration != 0;
	VRVendorRuntimeLifecycleSnapshot lifecycle{};
	uint64_t revision = 0;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		auto& target = a_upscaleMethod == UpscaleMethod::kDLSS ?
		                   vrRenderScaleTransitionController.dlssLifecycle :
		                   vrRenderScaleTransitionController.fsrLifecycle;
		const uint32_t requestedGeneration = a_generation != 0 ? a_generation : target.requestedGeneration;
		if (requestedGeneration != target.requestedGeneration) {
			target.attempts = 0;
			target.deferrals = 0;
			target.failures = 0;
		}
		target.method = a_upscaleMethod;
		target.backend = a_upscaleMethod == UpscaleMethod::kDLSS ?
		                     VRRenderScaleBackendKind::DLSS :
		                     (vrRenderScaleTransitionController.relatchPlan.target.method == UpscaleMethod::kFSR ?
									 vrRenderScaleTransitionController.relatchPlan.target.backend :
									 VRRenderScaleBackendKind::FSRHost);
		target.phase = a_phase;
		target.transitionEpoch = vrRenderScaleTransitionController.targetEpoch;
		target.requestedGeneration = requestedGeneration;
		target.runtimeGeneration = runtimeGeneration;
		target.stateFrame = frame;
		target.resourcesPresent = resourcesPresent;
		const auto increment = [](uint32_t& a_value) {
			if (a_value != std::numeric_limits<uint32_t>::max())
				++a_value;
		};
		if (a_phase == VRVendorRuntimeLifecyclePhase::Creating)
			increment(target.attempts);
		if (a_phase == VRVendorRuntimeLifecyclePhase::WaitingForDrain)
			increment(target.deferrals);
		if (a_phase == VRVendorRuntimeLifecyclePhase::Failed)
			increment(target.failures);
		target.readyForContract =
			a_phase == VRVendorRuntimeLifecyclePhase::Ready &&
			resourcesPresent &&
			requestedGeneration != 0 &&
			runtimeGeneration == requestedGeneration;
		lifecycle = target;
		revision = ++vrRenderScaleTransitionController.revision;
	}

	if (ShouldEmitUpscalingDiagLogs()) {
		logger::debug(
			"[VRRenderScale][VendorLifecycle] revision={} epoch={} method={} backend={} phase={} requestedGeneration={} runtimeGeneration={} resources={} ready={} attempts={} deferrals={} failures={}{}{}",
			revision,
			lifecycle.transitionEpoch,
			magic_enum::enum_name(lifecycle.method),
			magic_enum::enum_name(lifecycle.backend),
			GetVRVendorRuntimeLifecyclePhaseName(lifecycle.phase),
			lifecycle.requestedGeneration,
			lifecycle.runtimeGeneration,
			BoolText(lifecycle.resourcesPresent),
			BoolText(lifecycle.readyForContract),
			lifecycle.attempts,
			lifecycle.deferrals,
			lifecycle.failures,
			a_reason && *a_reason ? " reason=" : "",
			a_reason && *a_reason ? a_reason : "");
	}
	if (a_phase == VRVendorRuntimeLifecyclePhase::Failed)
		RecordVRRenderScaleTransitionFailure(VRRenderScaleFailureKind::Backend);
}

void Upscaling::ArchiveVRRenderScaleTransitionMetricsLocked(bool a_completed, bool a_superseded, uint32_t a_frame)
{
	auto& metrics = vrRenderScaleTransitionController.metrics;
	if (!metrics.current.valid)
		return;

	metrics.current.completed = a_completed;
	metrics.current.superseded = a_superseded;
	const uint32_t startFrame = metrics.current.requestedFrame;
	metrics.current.totalFrames = startFrame != 0 ? ElapsedFrames(startFrame, a_frame) : 0u;
	metrics.recent[metrics.nextIndex] = metrics.current;
	metrics.nextIndex = (metrics.nextIndex + 1u) % static_cast<uint32_t>(metrics.recent.size());
	metrics.count = std::min<uint32_t>(metrics.count + 1u, static_cast<uint32_t>(metrics.recent.size()));
	metrics.current = {};
}

void Upscaling::RecordVRRenderScaleTransitionRetry(VRRenderScaleRetryKind a_kind)
{
	bool recorded = false;
	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		if (!metrics.valid)
			return;

		const auto increment = [](uint32_t& a_value) {
			if (a_value != std::numeric_limits<uint32_t>::max())
				++a_value;
		};
		increment(metrics.retries);
		switch (a_kind) {
		case VRRenderScaleRetryKind::Pressure:
			increment(metrics.pressureDeferrals);
			break;
		case VRRenderScaleRetryKind::Retirement:
			increment(metrics.retirementDeferrals);
			break;
		case VRRenderScaleRetryKind::Backend:
			increment(metrics.backendDeferrals);
			break;
		default:
			break;
		}
		++vrRenderScaleTransitionController.revision;
		recorded = true;
	}
	if (recorded)
		RecordVRRenderScaleStressEvent(VRRenderScaleStressEventType::Retry, a_kind);
}

void Upscaling::RecordVRRenderScaleTransitionFailure(VRRenderScaleFailureKind a_kind)
{
	if (a_kind == VRRenderScaleFailureKind::None)
		return;
	if (a_kind == VRRenderScaleFailureKind::OutOfMemory) {
		const uint32_t failureFrame = globals::state ? std::max(globals::state->frameCount, 1u) : 1u;
		vrRenderScaleLastOutOfMemoryFailureFrame.store(failureFrame, std::memory_order_release);
	}

	{
		std::scoped_lock lock(vrRenderScaleTransitionControllerMutex);
		auto& metrics = vrRenderScaleTransitionController.metrics.current;
		if (metrics.valid) {
			const auto increment = [](uint32_t& a_value) {
				if (a_value != std::numeric_limits<uint32_t>::max())
					++a_value;
			};
			increment(metrics.failures);
			if (a_kind == VRRenderScaleFailureKind::OutOfMemory)
				increment(metrics.outOfMemoryFailures);
			if (a_kind == VRRenderScaleFailureKind::DeviceLost)
				increment(metrics.deviceLostFailures);
			metrics.lastFailure = a_kind;
			++vrRenderScaleTransitionController.revision;
		}
	}
	RecordVRRenderScaleStressEvent(VRRenderScaleStressEventType::Failure, VRRenderScaleRetryKind::Other, a_kind);
}

void Upscaling::RecordVRRenderScaleCoalescedDuplicate()
{
	std::scoped_lock lock(vrRenderScaleStressSessionMutex);
	if (!vrRenderScaleStressSession.active)
		return;
	if (vrRenderScaleStressSession.coalescedDuplicateCount !=
		std::numeric_limits<uint32_t>::max()) {
		++vrRenderScaleStressSession.coalescedDuplicateCount;
	}
}

void Upscaling::RecordVRRenderScaleStressEvent(VRRenderScaleStressEventType a_type, VRRenderScaleRetryKind a_retryKind, VRRenderScaleFailureKind a_failureKind)
{
	uint64_t activeSessionID = 0;
	{
		// Normal gameplay records transition metrics even when DevBench is not
		// capturing. Avoid the additional controller/backend snapshots unless a
		// real stress session currently owns them.
		std::scoped_lock lock(vrRenderScaleStressSessionMutex);
		if (!vrRenderScaleStressSession.active)
			return;
		activeSessionID = vrRenderScaleStressSession.sessionID;
	}

	const auto controller = GetVRRenderScaleTransitionSnapshot();
	const auto vendorWorkGate = GetVRVendorWorkGateSnapshot();
	const auto& profile =
		a_type == VRRenderScaleStressEventType::Request ? controller.requested :
		a_type == VRRenderScaleStressEventType::Applied ? controller.applied :
		a_type == VRRenderScaleStressEventType::Stable  ? controller.stable :
		controller.applying.valid                       ? controller.applying :
		controller.requested.valid                      ? controller.requested :
		controller.applied.valid                        ? controller.applied :
														  controller.stable;
	VRRenderScaleTransitionMetrics metrics{};
	const bool transitionEvent =
		a_type != VRRenderScaleStressEventType::SessionStarted &&
		a_type != VRRenderScaleStressEventType::SessionStopped;
	if (transitionEvent) {
		if (controller.metrics.current.valid) {
			metrics = controller.metrics.current;
		} else if (controller.metrics.count != 0) {
			const uint32_t index =
				(controller.metrics.nextIndex + static_cast<uint32_t>(controller.metrics.recent.size()) - 1u) %
				static_cast<uint32_t>(controller.metrics.recent.size());
			metrics = controller.metrics.recent[index];
		}
	}

	std::scoped_lock lock(vrRenderScaleStressSessionMutex);
	if (!vrRenderScaleStressSession.active ||
		vrRenderScaleStressSession.sessionID != activeSessionID) {
		return;
	}

	VRRenderScaleStressEvent event{};
	event.sessionID = activeSessionID;
	event.frame = globals::state ? std::max(globals::state->frameCount, 1u) : 0u;
	event.lastFrame = event.frame;
	event.type = a_type;
	event.requestID = profile.requestID;
	event.transitionEpoch = profile.transitionEpoch != 0 ? profile.transitionEpoch : controller.targetEpoch;
	event.origin = profile.origin;
	event.method = profile.method;
	event.active = profile.active;
	event.qualityMode = profile.qualityMode;
	event.dlssPreset = profile.dlssPreset;
	event.state = controller.state;
	event.pressure = controller.memory.pressure;
	event.retryKind = a_retryKind;
	event.failureKind = a_failureKind;
	event.usageBytes = controller.memory.currentUsageBytes;
	event.systemCommitBytes = controller.memory.systemCommitBytes;
	event.processPrivateUsageBytes = controller.memory.processPrivateUsageBytes;
	event.retries = metrics.retries;
	event.failures = metrics.failures;
	event.fidelityMismatches = metrics.fidelityMismatches;
	event.vendorWorkGateState = vendorWorkGate.state;
	event.vendorWorkGateMask = vendorWorkGate.activeMask;
	event.vendorWorkGateEffectiveMask = vendorWorkGate.effectiveLifecycleMask;
	event.vendorWorkGateEpoch = vendorWorkGate.stateEpoch;
	event.vendorLifecycleGateRelevant = vendorWorkGate.lifecycleGateRelevant;
	event.vendorLifecycleMutationDeferred = vendorWorkGate.lifecycleMutationDeferred;
	event.existingVendorDispatchReady = vendorWorkGate.existingVendorDispatchReady;

	if (event.type == VRRenderScaleStressEventType::Retry && vrRenderScaleStressSession.count != 0) {
		const uint32_t capacity = static_cast<uint32_t>(vrRenderScaleStressSession.events.size());
		const uint32_t previousIndex =
			(vrRenderScaleStressSession.nextIndex + capacity - 1u) % capacity;
		auto& previous = vrRenderScaleStressSession.events[previousIndex];
		const bool equivalentRetry =
			previous.type == VRRenderScaleStressEventType::Retry &&
			previous.requestID == event.requestID &&
			previous.transitionEpoch == event.transitionEpoch &&
			previous.origin == event.origin &&
			previous.method == event.method &&
			previous.active == event.active &&
			previous.qualityMode == event.qualityMode &&
			previous.dlssPreset == event.dlssPreset &&
			previous.state == event.state &&
			previous.pressure == event.pressure &&
			previous.retryKind == event.retryKind &&
			previous.failureKind == event.failureKind &&
			previous.vendorWorkGateState == event.vendorWorkGateState &&
			previous.vendorLifecycleGateRelevant == event.vendorLifecycleGateRelevant &&
			previous.vendorLifecycleMutationDeferred == event.vendorLifecycleMutationDeferred &&
			previous.existingVendorDispatchReady == event.existingVendorDispatchReady;
		if (equivalentRetry) {
			previous.lastFrame = event.lastFrame;
			if (previous.occurrences != std::numeric_limits<uint32_t>::max())
				++previous.occurrences;
			previous.usageBytes = event.usageBytes;
			previous.systemCommitBytes = event.systemCommitBytes;
			previous.processPrivateUsageBytes = event.processPrivateUsageBytes;
			previous.retries = event.retries;
			previous.failures = event.failures;
			previous.fidelityMismatches = event.fidelityMismatches;
			return;
		}
	}

	event.sequence = vrRenderScaleStressSession.nextSequence++;
	vrRenderScaleStressSession.events[vrRenderScaleStressSession.nextIndex] = event;
	vrRenderScaleStressSession.nextIndex =
		(vrRenderScaleStressSession.nextIndex + 1u) % static_cast<uint32_t>(vrRenderScaleStressSession.events.size());
	if (vrRenderScaleStressSession.count < vrRenderScaleStressSession.events.size()) {
		++vrRenderScaleStressSession.count;
	} else if (vrRenderScaleStressSession.overwrittenEvents != std::numeric_limits<uint32_t>::max()) {
		++vrRenderScaleStressSession.overwrittenEvents;
	}
}

void Upscaling::MarkVRUpscalingTransitionQueued(VRUpscalingTransitionOrigin a_origin)
{
	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : 1u;
	{
		std::scoped_lock lock(pendingVRRenderScaleRequestMutex);
		if (!pendingVRRenderScaleRequest)
			return;

		auto refreshedRequest = *pendingVRRenderScaleRequest;
		if (ShouldStoreVRUpscalingTransitionOrigin(refreshedRequest.origin, a_origin, true))
			refreshedRequest.origin = a_origin;
		refreshedRequest.queuedFrame = frame;
		pendingVRRenderScaleRequest = refreshedRequest;
	}
	InvalidateFrameScopedUpscalingState();
	SetVRRenderScaleTransitionState(VRRenderScaleTransitionState::WaitingForSafePoint, "transition safety deferral");
}

void Upscaling::ClearPendingVRUpscalingTransition()
{
	{
		std::scoped_lock lock(pendingVRRenderScaleRequestMutex);
		pendingVRRenderScaleRequest.reset();
		deferredVRRenderScaleRequestAfterPhysicalRecovery.reset();
		deferredVRRenderScaleRequestPending.store(
			false,
			std::memory_order_release);
		latestVRRenderScaleRequestID.store(0, std::memory_order_release);
	}
	ResetVRRenderScaleTransitionController("pending request cleared");
	InvalidateFrameScopedUpscalingState();
}

bool Upscaling::HasPendingVRUpscalingTransition() const
{
	return GetPendingVRRenderScaleDesiredProfile().HasPendingSettings();
}

bool Upscaling::HasPendingVRRenderScaleTransition() const
{
	const auto desiredProfile = GetPendingVRRenderScaleDesiredProfile();
	if (!desiredProfile.HasPendingSettings())
		return false;

	return IsVRRenderScaleCurrentOrTargetRelevant(*this);
}

bool Upscaling::HasUnresolvedVRRenderScalePhysicalRecovery() const
{
	// Same four conditions QueueVRRenderScaleRequest defers on. Kept in one place
	// so the envelope and the request queue cannot drift apart.
	return vrRenderScaleUnresolvedPhysicalMutationEpoch.load(std::memory_order_acquire) != 0 ||
	       vrRenderScalePostMutationSerializationEpoch.load(std::memory_order_acquire) != 0 ||
	       vrRenderScalePreMutationNativeFallbackAdmissionActive.load(std::memory_order_acquire) ||
	       HasLiveVRRenderScaleProviderNeutralRecoveryWorker();
}

bool Upscaling::HotEnvelopeMayRelax(uint32_t a_qualityMode) const
{
	if (HasUnresolvedVRRenderScalePhysicalRecovery()) {
		// A relatch is in flight. Its armed mutation epoch is cleared only by its
		// own completion or no-op path, so skipping it here strands the epoch and
		// blocks every subsequent request - the run-2 failure.
		//
		// Log which of the four held, deduplicated, so the next session either
		// confirms this mechanism or rules it out instead of leaving it argued.
		static uint32_t loggedMask = 0xFFFFFFFFu;
		const uint32_t mask =
			(vrRenderScaleUnresolvedPhysicalMutationEpoch.load(std::memory_order_acquire) != 0 ? 1u : 0u) |
			(vrRenderScalePostMutationSerializationEpoch.load(std::memory_order_acquire) != 0 ? 2u : 0u) |
			(vrRenderScalePreMutationNativeFallbackAdmissionActive.load(std::memory_order_acquire) ? 4u : 0u) |
			(HasLiveVRRenderScaleProviderNeutralRecoveryWorker() ? 8u : 0u);
		if (mask != loggedMask) {
			loggedMask = mask;
			logger::info(
				"[HotEnvelope][inflight] relaxation refused for quality {}: mutationEpoch={} postMutationSerialization={} preMutationFallback={} recoveryWorker={}",
				a_qualityMode,
				(mask & 1u) != 0,
				(mask & 2u) != 0,
				(mask & 4u) != 0,
				(mask & 8u) != 0);
		}
		return false;
	}
	return perfMode.HotEnvelopeFits(settings, a_qualityMode);
}

bool Upscaling::ShouldStageVRRenderScaleTransition(bool a_renderScaleModeEnabled, uint32_t a_qualityMode) const
{
	if (!globals::game::isVR || !IsRenderScaleMethodEligible(GetConfiguredUpscaleMethodForTransition()))
		return false;

	const uint32_t qualityMode = std::min(a_qualityMode, kQualityModeMaxIndex);
	const uint32_t effectiveQualityMode = GetEffectiveUpscalingQualityMode();
	const bool currentRenderScaleMode =
		IsRenderScaleModeRequested() &&
		IsRenderScaleQualityMode(effectiveQualityMode);
	const bool targetRenderScaleQuality = IsRenderScaleQualityMode(qualityMode);
	const bool targetRenderScaleMode = a_renderScaleModeEnabled && targetRenderScaleQuality;
	const bool targetPerfMode = targetRenderScaleMode;
	const bool currentPerfMode =
		GetPerfModeRequested() ||
		IsVRRenderScaleModeLatched() ||
		perfMode.HasRestartRequiredChange();

	if (currentRenderScaleMode != targetRenderScaleMode)
		return true;

	// Hot-Envelope (experimental): a quality that renders inside the targets
	// already allocated needs no render-scale transition at all. Only the logical
	// extent moves, which ApplyDynamicResolutionState handles on its own.
	//
	// A quality ABOVE the envelope does not fit, so this still returns true and
	// the transition stages exactly as before. HotEnvelopeFits is false whenever
	// the feature is off, so the shipped path is unchanged.
	if (effectiveQualityMode != qualityMode &&
		!HotEnvelopeMayRelax(qualityMode) &&
		(currentRenderScaleMode || targetRenderScaleMode || IsVRRenderScaleModeLatched() || perfMode.HasRestartRequiredChange()))
		return true;

	return currentPerfMode != targetPerfMode;
}

bool Upscaling::ShouldDeferVRUpscalingTransitionSettings() const
{
	if (!globals::game::isVR)
		return false;

	const auto desiredProfile = GetPendingVRRenderScaleDesiredProfile();
	const bool pendingRenderScaleTransition = HasPendingVRRenderScaleTransition();
	const bool bufferedStabilizerDoorHandoff =
		desiredProfile.transitionEpoch != 0 &&
		IsBufferedVRFpsStabilizerDoorHandoff(desiredProfile);
	if (!pendingRenderScaleTransition && !bufferedStabilizerDoorHandoff)
		return false;

	const auto* state = globals::state;
	if (!state)
		return false;

	const auto transitionOrigin = desiredProfile.origin;
	if (ShouldDeferExplicitVRRenderScaleRelatch(
			*this,
			transitionOrigin,
			state,
			desiredProfile.transitionEpoch)) {
		return true;
	}

	if (!IsPendingVRRenderScaleActivationTarget(*this))
		return false;

	if (postLoadRuntimeResetPending.load(std::memory_order_acquire))
		return true;

	return UsesVRRenderScaleStartupActivationProtection(*this, state, true);
}

bool Upscaling::ShouldWaitForVRUpscalingTransitionDelay() const
{
	const auto desiredProfile = GetPendingVRRenderScaleDesiredProfile();
	const bool bufferedStabilizerDoorHandoff =
		desiredProfile.transitionEpoch != 0 &&
		IsBufferedVRFpsStabilizerDoorHandoff(desiredProfile);
	if (!HasPendingVRRenderScaleTransition() && !bufferedStabilizerDoorHandoff)
		return false;

	const uint32_t queuedFrame = desiredProfile.queuedFrame;
	if (queuedFrame == 0)
		return false;

	const uint32_t currentFrame = globals::state ? std::max(globals::state->frameCount, 1u) : queuedFrame;
	return currentFrame - queuedFrame < kVRUpscalingTransitionApplyDelayFrames;
}

void Upscaling::MarkPerfModeRenderTargetRecreateQueued(uint32_t a_delayFrames)
{
	const std::scoped_lock queueLock(
		perfModeRenderTargetRecreateQueueMutex);
	const uint32_t frame = globals::state ? std::max(globals::state->frameCount, 1u) : 1u;
	const uint32_t delayFrames = a_delayFrames != 0 ? a_delayFrames : kVRUpscalingTransitionApplyDelayFrames;
	pendingPerfModeRenderTargetRecreateFrame.store(frame, std::memory_order_release);
	pendingPerfModeRenderTargetRecreateNativeRestoreRetirementSerial.store(
		0,
		std::memory_order_release);
	const uint32_t previousDelay = pendingPerfModeRenderTargetRecreateDelayFrames.load(std::memory_order_acquire);
	if (previousDelay == 0 || delayFrames > previousDelay)
		pendingPerfModeRenderTargetRecreateDelayFrames.store(delayFrames, std::memory_order_release);
}

bool Upscaling::ShouldWaitForPerfModeRenderTargetRecreateDelay(
	bool a_bypassMultiFrameDelay) const
{
	const std::scoped_lock queueLock(
		perfModeRenderTargetRecreateQueueMutex);
	const uint32_t queuedFrame = pendingPerfModeRenderTargetRecreateFrame.load(std::memory_order_acquire);
	if (queuedFrame == 0)
		return false;

	uint32_t delayFrames = pendingPerfModeRenderTargetRecreateDelayFrames.load(std::memory_order_acquire);
	if (delayFrames == 0)
		delayFrames = kVRUpscalingTransitionApplyDelayFrames;

	const uint32_t currentFrame = globals::state ? std::max(globals::state->frameCount, 1u) : queuedFrame;
	return VRVendorRelatchPolicy::ShouldDeferRelatchForRetryPacing({
		.queuedFrame = queuedFrame,
		.currentFrame = currentFrame,
		.delayFrames = delayFrames,
		.bypassMultiFrameDelay = a_bypassMultiFrameDelay,
	});
}

void Upscaling::ApplyPendingVRUpscalingTransition()
{
	if (!globals::game::isVR)
		return;

	if (!HasPendingVRUpscalingTransition())
		return;
	if (vrRenderScaleUnresolvedPhysicalMutationEpoch.load(
			std::memory_order_acquire) != 0 ||
		vrRenderScalePostMutationSerializationEpoch.load(
			std::memory_order_acquire) != 0) {
		std::optional<VRRenderScaleDesiredProfile> deferred;
		{
			std::scoped_lock lock(pendingVRRenderScaleRequestMutex);
			if (pendingVRRenderScaleRequest &&
				!IsVRRenderScaleRecoveryOrigin(
					pendingVRRenderScaleRequest->origin)) {
				(void)StoreDeferredVRRenderScaleRequestLatestWinsLocked(
					*pendingVRRenderScaleRequest);
				deferred = pendingVRRenderScaleRequest;
				pendingVRRenderScaleRequest.reset();
			}
		}
		if (deferred) {
			SuspendVRRenderScaleControllerForDeferredRequest(*deferred);
			logger::warn(
				"[VRRenderScale] Suspended already-pending request id={} epoch={} until unresolved physical recovery completes.",
				deferred->requestID,
				deferred->transitionEpoch);
			return;
		}
	}

	if (ApplyOpenCompositeUpscalingBlocker(true))
		return;

	static bool loggedVRUpscalingTransitionDefer = false;
	if (ShouldDeferVRUpscalingTransitionSettings()) {
		MarkVRUpscalingTransitionQueued(GetPendingVRRenderScaleDesiredProfile().origin);
		if (HasPendingVRRenderScaleTransition() && !loggedVRUpscalingTransitionDefer) {
			logger::debug("[VRRenderScale] Pending VR upscaling transition waiting for protected post-load/menu presentation to clear.");
			loggedVRUpscalingTransitionDefer = true;
		}
		return;
	}
	loggedVRUpscalingTransitionDefer = false;

	if (ShouldWaitForVRUpscalingTransitionDelay()) {
		SetVRRenderScaleTransitionState(VRRenderScaleTransitionState::WaitingForSafePoint, "request coalescing delay");
		return;
	}

	const auto pendingRequest = TakePendingVRRenderScaleRequest();
	if (!pendingRequest)
		return;

	const VRRenderScaleDesiredProfile request = *pendingRequest;
	if (!IsLatestVRRenderScaleRequest(request.requestID)) {
		if (ShouldEmitUpscalingDiagLogs()) {
			logger::debug(
				"[VRRenderScale][Diag] Dropped superseded immutable request id={} latest={}",
				request.requestID,
				latestVRRenderScaleRequestID.load(std::memory_order_acquire));
		}
		return;
	}
	if (!RecordVRRenderScaleTransitionPreparing(request)) {
		if (ShouldEmitUpscalingDiagLogs()) {
			logger::debug(
				"[VRRenderScale][Controller] Dropped stale consumed request id={} epoch={} currentEpoch={}.",
				request.requestID,
				request.transitionEpoch,
				GetVRRenderScaleTransitionSnapshot().targetEpoch);
		}
		return;
	}

	const auto targetMethod = request.method;
	const auto transitionOrigin = request.origin;
	const uint32_t targetQualityMode = std::min(request.qualityMode, kQualityModeMaxIndex);
	const bool targetRenderScaleMode =
		IsRenderScaleMethodEligible(targetMethod) &&
		request.renderScaleModeEnabled &&
		IsRenderScaleQualityMode(targetQualityMode);
	const bool targetPerfMode = request.perfModeEnabled && targetRenderScaleMode;
	const uint32_t targetDLSSPreset = ClampDLSSPresetUInt(request.dlssPreset);
	const auto& activeBoot = perfMode.GetBootSnapshot();
	const bool methodChangedFromActiveContract =
		activeBoot.valid &&
		activeBoot.active &&
		activeBoot.method != targetMethod;

	uint32_t* currentUpscaleMode =
		(streamline.featureDLSS || targetMethod == UpscaleMethod::kDLSS) ?
			&settings.upscaleMethod :
			&settings.upscaleMethodNoDLSS;
	*currentUpscaleMode = static_cast<uint32_t>(targetMethod);

	const bool qualitySettingChanged =
		settings.qualityMode != targetQualityMode;
	const bool dlssPresetSettingChanged =
		settings.dlssPreset != targetDLSSPreset;
	const bool fsr4RuntimeSettingChanged =
		settings.fsr4RuntimeEnable != request.fsr4RuntimeEnabled;
	const uint32_t requestedRenderScaleMode =
		targetRenderScaleMode ? 1u : 0u;
	const bool renderScaleModeChanged =
		settings.renderScaleMode != requestedRenderScaleMode;
	settings.qualityMode = targetQualityMode;
	settings.dlssPreset = targetDLSSPreset;
	settings.fsr4RuntimeEnable = request.fsr4RuntimeEnabled;
	settings.renderScaleMode = requestedRenderScaleMode;

	const bool qualityChanged =
		IsRenderScaleMethodEligible(targetMethod) && qualitySettingChanged;
	const bool presetChanged =
		targetMethod == UpscaleMethod::kDLSS &&
		dlssPresetSettingChanged;
	const bool fsr4RuntimeSelectionChanged =
		targetMethod == UpscaleMethod::kFSR &&
		fsr4RuntimeSettingChanged;
	const bool changed =
		qualityChanged ||
		presetChanged ||
		fsr4RuntimeSelectionChanged;

	if (!IsRenderScaleMethodEligible(targetMethod)) {
		if (ClampToggleUInt(settings.perfMode) != 0 || IsVRRenderScaleModeLatched() || perfMode.HasRestartRequiredChange())
			SetPerfModeRequested(false, "VR upscaling deferred transition", false, transitionOrigin);

		if (renderScaleModeChanged || methodChangedFromActiveContract) {
			InvalidateFrameScopedUpscalingState();
			RequestHistoryReset();
		}
		if (ShouldEmitUpscalingDiagLogs()) {
			logger::debug(
				"[VRRenderScale][Diag] Applied immutable request id={} origin={} method={} renderScaleMode=false quality={}",
				request.requestID,
				magic_enum::enum_name(transitionOrigin),
				magic_enum::enum_name(targetMethod),
				targetQualityMode);
		}
		if (pendingPerfModeRenderTargetRecreate.load(std::memory_order_acquire))
			SetVRRenderScaleTransitionState(VRRenderScaleTransitionState::WaitingForSafePoint, "inactive target relatch queued");
		else {
			if (PublishVRRenderScaleTransitionApplied(
					transitionOrigin,
					false,
					request.transitionEpoch)) {
				const float2 nativeSize = perfMode.GetDisplayScreenSize();
				CompleteVRRenderScaleInfoTransition(
					request.transitionEpoch,
					"request already applied",
					false,
					targetMethod,
					nativeSize,
					nativeSize);
			}
		}
		return;
	}

	if (ClampToggleUInt(settings.perfMode) != static_cast<uint32_t>(targetPerfMode) ||
		IsVRRenderScaleModeLatched() != targetPerfMode ||
		perfMode.HasRestartRequiredChange() ||
		(targetPerfMode &&
			!IsVRRenderScalePhysicalContractConverged(
				targetMethod,
				targetQualityMode,
				request.fsr4RuntimeEnabled))) {
		SetPerfModeRequested(targetPerfMode, "VR upscaling deferred transition", false, transitionOrigin);
	}
	if (targetPerfMode && methodChangedFromActiveContract)
		RequestPerfModeRenderTargetRecreate("VR upscaling method change", transitionOrigin);
	if (targetPerfMode &&
		fsr4RuntimeSelectionChanged &&
		!IsVRRenderScalePhysicalContractConverged(
			targetMethod,
			targetQualityMode,
			request.fsr4RuntimeEnabled)) {
		RequestPerfModeRenderTargetRecreate("VR FSR runtime path change", transitionOrigin);
	}

	if (changed || renderScaleModeChanged || methodChangedFromActiveContract) {
		InvalidateFrameScopedUpscalingState();
		RequestHistoryReset();
		if (targetMethod == UpscaleMethod::kDLSS)
			pendingDLSSHistoryReset.store(true, std::memory_order_release);
		// Hot-Envelope (experimental): same fits-check as the immediate path. A
		// destination quality that renders inside the current allocation needs the
		// history reset above, but no physical recreate.
		const bool profileQualityNeedsRealloc =
			qualityChanged && !HotEnvelopeMayRelax(targetQualityMode);
		if ((profileQualityNeedsRealloc || renderScaleModeChanged) && (IsVRRenderScaleModeLatched() || GetPerfModeRequested()))
			RequestPerfModeRenderTargetRecreate("VR render-scale profile change", transitionOrigin);
	}

	if (ShouldEmitUpscalingDiagLogs()) {
		logger::debug(
			"[VRRenderScale][Diag] Applied immutable request id={} origin={} method={} renderScaleMode={} perfMode={} quality={} dlssPreset={} changed={} presetChanged={}",
			request.requestID,
			magic_enum::enum_name(transitionOrigin),
			magic_enum::enum_name(targetMethod),
			BoolText(targetRenderScaleMode),
			BoolText(targetPerfMode),
			targetQualityMode,
			targetDLSSPreset,
			BoolText(changed || renderScaleModeChanged || methodChangedFromActiveContract),
			BoolText(presetChanged));
	}

	if (pendingPerfModeRenderTargetRecreate.load(std::memory_order_acquire))
		SetVRRenderScaleTransitionState(VRRenderScaleTransitionState::WaitingForSafePoint, "profile relatch queued");
	else {
		if (PublishVRRenderScaleTransitionApplied(
				transitionOrigin,
				false,
				request.transitionEpoch)) {
			const float2 displaySize = perfMode.GetDisplayScreenSize();
			const float2 renderSize = targetPerfMode ?
			                              perfMode.GetRenderScreenSize() :
			                              displaySize;
			CompleteVRRenderScaleInfoTransition(
				request.transitionEpoch,
				"request already applied",
				targetPerfMode,
				targetMethod,
				displaySize,
				renderSize);
		}
	}
}

void Upscaling::FillMenuCameraMotionVectors()
{
	menuCameraMVsValid = false;

	auto renderer = globals::game::renderer;
	auto context = globals::d3d::context;
	if (!renderer || !context || !cameraMotionVectorsCB)
		return;

	auto& motionVector = renderer->GetRuntimeData().renderTargets[RE::RENDER_TARGETS::kMOTION_VECTOR];
	auto& depth = renderer->GetDepthStencilData().depthStencils[RE::RENDER_TARGETS_DEPTHSTENCIL::kMAIN];

	auto* pixelShader = GetCameraMotionVectorsPS();
	auto* vertexShader = GetUpscaleVS();
	if (!pixelShader || !vertexShader || !motionVector.RTV || !motionVector.texture || !depth.depthSRV)
		return;

	CS_PROFILE_SCOPE("Upscaling::MenuCameraMotionVectors");

	CameraMotionVectorsCB cbData{};
	const uint32_t numEyes = globals::game::isVR ? 2u : 1u;
	for (uint32_t eyeIndex = 0; eyeIndex < numEyes; ++eyeIndex) {
		// Inversion is convention-safe on the raw cb12 bytes; composition with the previous
		// view-proj stays in the shader so the mul() convention matches FrameBuffer usage.
		cbData.curViewProjUnjitteredInverse[eyeIndex] =
			globals::game::frameBufferCached.GetCameraViewProjUnjittered(eyeIndex).Invert();
		cbData.prevViewProjUnjittered[eyeIndex] =
			globals::game::frameBufferCached.GetCameraPreviousViewProjUnjittered(eyeIndex);
	}
	cameraMotionVectorsCB->Update(cbData);

	ID3D11VertexShader* previousVS = nullptr;
	ID3D11PixelShader* previousPS = nullptr;
	ID3D11HullShader* previousHS = nullptr;
	ID3D11DomainShader* previousDS = nullptr;
	ID3D11GeometryShader* previousGS = nullptr;
	ID3D11ShaderResourceView* previousSRV = nullptr;
	ID3D11Buffer* previousPSCB1 = nullptr;
	std::array<ID3D11RenderTargetView*, D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT> previousRTVs{};
	ID3D11DepthStencilView* previousDSV = nullptr;
	ID3D11BlendState* previousBlendState = nullptr;
	FLOAT previousBlendFactor[4] = {};
	UINT previousSampleMask = 0;
	ID3D11DepthStencilState* previousDepthStencilState = nullptr;
	UINT previousStencilRef = 0;
	ID3D11RasterizerState* previousRasterizerState = nullptr;
	std::array<D3D11_VIEWPORT, D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE> previousViewports{};
	UINT previousViewportCount = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
	D3D11_PRIMITIVE_TOPOLOGY previousTopology = D3D11_PRIMITIVE_TOPOLOGY_UNDEFINED;
	ID3D11InputLayout* previousInputLayout = nullptr;

	context->VSGetShader(&previousVS, nullptr, nullptr);
	context->PSGetShader(&previousPS, nullptr, nullptr);
	context->HSGetShader(&previousHS, nullptr, nullptr);
	context->DSGetShader(&previousDS, nullptr, nullptr);
	context->GSGetShader(&previousGS, nullptr, nullptr);
	context->PSGetShaderResources(0, 1, &previousSRV);
	context->PSGetConstantBuffers(1, 1, &previousPSCB1);
	context->OMGetRenderTargets(static_cast<UINT>(previousRTVs.size()), previousRTVs.data(), &previousDSV);
	context->OMGetBlendState(&previousBlendState, previousBlendFactor, &previousSampleMask);
	context->OMGetDepthStencilState(&previousDepthStencilState, &previousStencilRef);
	context->RSGetState(&previousRasterizerState);
	context->RSGetViewports(&previousViewportCount, previousViewports.data());
	context->IAGetPrimitiveTopology(&previousTopology);
	context->IAGetInputLayout(&previousInputLayout);

	auto restoreState = ScopeExit([&]() {
		ID3D11ShaderResourceView* nullSRV = nullptr;
		context->PSSetShaderResources(0, 1, &nullSRV);

		context->VSSetShader(previousVS, nullptr, 0);
		context->PSSetShader(previousPS, nullptr, 0);
		context->HSSetShader(previousHS, nullptr, 0);
		context->DSSetShader(previousDS, nullptr, 0);
		context->GSSetShader(previousGS, nullptr, 0);
		context->PSSetShaderResources(0, 1, &previousSRV);
		context->PSSetConstantBuffers(1, 1, &previousPSCB1);
		context->OMSetRenderTargets(static_cast<UINT>(previousRTVs.size()), previousRTVs.data(), previousDSV);
		context->OMSetBlendState(previousBlendState, previousBlendFactor, previousSampleMask);
		context->OMSetDepthStencilState(previousDepthStencilState, previousStencilRef);
		context->RSSetState(previousRasterizerState);
		context->RSSetViewports(previousViewportCount, previousViewportCount ? previousViewports.data() : nullptr);
		context->IASetPrimitiveTopology(previousTopology);
		context->IASetInputLayout(previousInputLayout);

		if (previousVS)
			previousVS->Release();
		if (previousPS)
			previousPS->Release();
		if (previousHS)
			previousHS->Release();
		if (previousDS)
			previousDS->Release();
		if (previousGS)
			previousGS->Release();
		if (previousSRV)
			previousSRV->Release();
		if (previousPSCB1)
			previousPSCB1->Release();
		for (auto* rtv : previousRTVs) {
			if (rtv)
				rtv->Release();
		}
		if (previousDSV)
			previousDSV->Release();
		if (previousBlendState)
			previousBlendState->Release();
		if (previousDepthStencilState)
			previousDepthStencilState->Release();
		if (previousRasterizerState)
			previousRasterizerState->Release();
		if (previousInputLayout)
			previousInputLayout->Release();
	});

	context->IASetInputLayout(nullptr);
	context->IASetVertexBuffers(0, 0, nullptr, nullptr, nullptr);
	context->IASetIndexBuffer(nullptr, DXGI_FORMAT_UNKNOWN, 0);
	context->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);

	context->VSSetShader(vertexShader, nullptr, 0);
	context->PSSetShader(pixelShader, nullptr, 0);
	context->GSSetShader(nullptr, nullptr, 0);
	context->HSSetShader(nullptr, nullptr, 0);
	context->DSSetShader(nullptr, nullptr, 0);

	context->OMSetRenderTargets(0, nullptr, nullptr);

	ID3D11ShaderResourceView* srvs[] = { depth.depthSRV };
	context->PSSetShaderResources(0, 1, srvs);

	// b1 is restored by the local state scope above.
	auto* constantBuffer = cameraMotionVectorsCB->CB();
	context->PSSetConstantBuffers(1, 1, &constantBuffer);

	context->OMSetBlendState(nullptr, nullptr, 0xffffffff);
	context->OMSetDepthStencilState(nullptr, 0);
	context->RSSetState(nullptr);

	D3D11_TEXTURE2D_DESC motionVectorDesc{};
	static_cast<ID3D11Texture2D*>(motionVector.texture)->GetDesc(&motionVectorDesc);
	D3D11_VIEWPORT viewport{};
	viewport.Width = static_cast<float>(motionVectorDesc.Width);
	viewport.Height = static_cast<float>(motionVectorDesc.Height);
	viewport.MaxDepth = 1.0f;
	context->RSSetViewports(1, &viewport);

	ID3D11RenderTargetView* rtv = motionVector.RTV;
	context->OMSetRenderTargets(1, &rtv, nullptr);
	context->Draw(3, 0);

	menuCameraMVsValid = true;
}

void Upscaling::PrepareMenuCameraMotionVectors()
{
	auto state = globals::state;
	if (!state) {
		menuCameraMVsValid = false;
		menuCameraMVsPreparedFrame = std::numeric_limits<uint32_t>::max();
		return;
	}

	const uint32_t frame = state->frameCount;
	if (menuCameraMVsPreparedFrame == frame)
		return;

	menuCameraMVsPreparedFrame = frame;
	menuCameraMVsValid = false;

	// Camera-only motion vectors are valid for a flat menu backdrop, but not when
	// a real scene rendered behind the menu (such as the VR Playroom). Preserve
	// that scene's motion vectors so head movement is not reconstructed as a
	// frozen, head-locked background.
	if (!IsMainMenuContextActive() ||
		IsLoadingMenuContextActive() ||
		state->lastWorldRenderFrame == frame)
		return;

	FillMenuCameraMotionVectors();
}

bool Upscaling::ShouldResetHistoryThisFrame() const
{
	return historyResetThisFrame;
}

void Upscaling::LatchHistoryResetForCurrentFrame()
{
	const uint32_t frame = globals::state ? globals::state->frameCount : 0;
	if (historyResetLatchedFrame == frame)
		return;

	historyResetLatchedFrame = frame;
	historyResetThisFrame = historyResetRequested;
	historyResetRequested = false;
}

void Upscaling::UpdateHistoryResetState(UpscaleMethod a_upscaleMethod)
{
	auto state = globals::state;
	if (!state)
		return;

	PrepareMenuCameraMotionVectors();

	const bool inWorld = state->inWorld;
	const bool inMapMenu = globals::game::ui ? globals::game::ui->IsMenuOpen(RE::MapMenu::MENU_NAME) : false;
	const bool mainMenuOpen = IsMainMenuContextActive();
	const bool loadingMenuOpen = IsLoadingMenuContextActive();
	const float2 screenSize = state->screenSize;
	EnsureRuntimeResolutionStateCurrent();
	float2 engineRenderSize = VRGeometry::ToFloat2(runtimeResolutionPlan.engineRenderSize);
	float2 finalOutputSize = runtimeResolutionPlan.finalOutputSize;
	if (engineRenderSize.x <= 0.0f || engineRenderSize.y <= 0.0f)
		engineRenderSize = Util::ConvertToDynamic(screenSize);
	if (finalOutputSize.x <= 0.0f || finalOutputSize.y <= 0.0f)
		finalOutputSize = screenSize;
	const auto resolutionOwner = runtimeResolutionPlan.owner;
	const bool foveatedDispatchEnabled = IsFoveatedVendorDispatchEnabled(a_upscaleMethod);
	const bool peripheryTAAEnabled = IsPeripheryTAAEnabled(a_upscaleMethod);
	const bool peripheryTAAPathActive = IsPeripheryTAAPathActive(a_upscaleMethod);
	const bool fsrRuntimePathActive = IsFSRRuntimePathActive(a_upscaleMethod);
	const bool fsrRuntimeFsr4Active = IsFSRRuntimeFsr4PathActive(a_upscaleMethod);
	const uint32_t qualityMode = GetRuntimeQualityMode();
	const auto foveatedProfile = GetFoveatedMaskProfileParams(settings, peripheryTAAEnabled);
	const float foveatedCenterScale = foveatedProfile.centerScale;
	const float foveatedCenterHorizontalScale = foveatedProfile.centerHorizontalScale;
	const float peripheryTAACenterBlendFeather = ClampPeripheryTAACenterBlendFeather(settings.periphery_taa_center_blend_feather);
	const float peripheryTAAOuterScale = ClampPeripheryTAAOuterScaleForCenter(
		settings.periphery_taa_outer_scale,
		foveatedCenterScale);
	const auto foveatedCenterOffsets = GetResolvedFoveatedMaskCenterOffsets(peripheryTAAEnabled);

	auto cameraCutDetected = []() {
		constexpr float kCameraCutDistanceThreshold = 2500.0f;  // ~35m teleport/cut in Skyrim units
		const float cutDistanceSq = kCameraCutDistanceThreshold * kCameraCutDistanceThreshold;

		auto exceededThreshold = [&](uint32_t eyeIndex) {
			const auto& currentPos = globals::game::frameBufferCached.GetCameraPosAdjust(eyeIndex);
			const auto& previousPos = globals::game::frameBufferCached.GetCameraPreviousPosAdjust(eyeIndex);
			const float dx = currentPos.x - previousPos.x;
			const float dy = currentPos.y - previousPos.y;
			const float dz = currentPos.z - previousPos.z;
			return (dx * dx + dy * dy + dz * dz) > cutDistanceSq;
		};

		if (globals::game::isVR)
			return exceededThreshold(0) || exceededThreshold(1);
		return exceededThreshold(0);
	};

	bool shouldReset = false;
	if (!historyResetTrackingInitialized) {
		shouldReset = true;
		historyResetTrackingInitialized = true;
	} else {
		const bool screenSizeChanged =
			std::abs(screenSize.x - previousHistoryScreenSize.x) > 0.5f ||
			std::abs(screenSize.y - previousHistoryScreenSize.y) > 0.5f;
		const bool scaleChanged =
			std::abs(resolutionScale.x - previousHistoryResolutionScale.x) > 1e-4f ||
			std::abs(resolutionScale.y - previousHistoryResolutionScale.y) > 1e-4f;
		const bool engineRenderSizeChanged =
			std::abs(engineRenderSize.x - previousHistoryEngineRenderSize.x) > 0.5f ||
			std::abs(engineRenderSize.y - previousHistoryEngineRenderSize.y) > 0.5f;
		const bool finalOutputSizeChanged =
			std::abs(finalOutputSize.x - previousHistoryFinalOutputSize.x) > 0.5f ||
			std::abs(finalOutputSize.y - previousHistoryFinalOutputSize.y) > 0.5f;
		const bool resolutionOwnerChanged = resolutionOwner != previousHistoryResolutionOwner;
		const bool qualityModeChanged = qualityMode != previousHistoryQualityMode;
		const bool worldStateChanged =
			inWorld != previousHistoryInWorld ||
			inMapMenu != previousHistoryInMapMenu;
		const bool methodChanged = a_upscaleMethod != previousHistoryUpscaleMethod;
		const bool fsrRuntimePathChanged = fsrRuntimePathActive != previousHistoryFSRRuntimePathActive;
		const bool fsrRuntimeVersionChanged =
			(fsrRuntimePathActive || previousHistoryFSRRuntimePathActive) &&
			fsrRuntimeFsr4Active != previousHistoryFSRRuntimeFsr4Active;
		const bool compareFoveatedScale = foveatedDispatchEnabled || previousHistoryFoveatedDispatch;
		const bool foveatedOffsetsChanged =
			compareFoveatedScale &&
			(std::abs(foveatedCenterOffsets[0].x - previousHistoryFoveatedCenterOffsets[0].x) > 1e-4f ||
				std::abs(foveatedCenterOffsets[0].y - previousHistoryFoveatedCenterOffsets[0].y) > 1e-4f ||
				std::abs(foveatedCenterOffsets[1].x - previousHistoryFoveatedCenterOffsets[1].x) > 1e-4f ||
				std::abs(foveatedCenterOffsets[1].y - previousHistoryFoveatedCenterOffsets[1].y) > 1e-4f);
		const bool foveatedChanged =
			foveatedDispatchEnabled != previousHistoryFoveatedDispatch ||
			(compareFoveatedScale && std::abs(foveatedCenterScale - previousHistoryFoveatedCenterScale) > 1e-4f) ||
			(compareFoveatedScale && std::abs(foveatedCenterHorizontalScale - previousHistoryFoveatedCenterHorizontalScale) > 1e-4f) ||
			foveatedOffsetsChanged;
		const bool longFrameGap = globals::game::deltaTime &&
		                          std::isfinite(*globals::game::deltaTime) &&
		                          *globals::game::deltaTime > 0.20f;
		const bool cameraCut = inWorld && cameraCutDetected();

		const bool effectivePeripheryTAAChanged =
			peripheryTAAEnabled != previousHistoryPeripheryTAA ||
			peripheryTAAPathActive != previousHistoryPeripheryTAAPathActive ||
			(peripheryTAAPathActive && (std::abs(peripheryTAAOuterScale - previousHistoryPeripheryTAAOuterScale) > 1e-4f ||
										   std::abs(peripheryTAACenterBlendFeather - previousHistoryPeripheryTAACenterBlendFeather) > 1e-4f));

		shouldReset =
			screenSizeChanged ||
			scaleChanged ||
			engineRenderSizeChanged ||
			finalOutputSizeChanged ||
			resolutionOwnerChanged ||
			qualityModeChanged ||
			worldStateChanged ||
			methodChanged ||
			fsrRuntimePathChanged ||
			fsrRuntimeVersionChanged ||
			foveatedChanged ||
			effectivePeripheryTAAChanged ||
			longFrameGap ||
			cameraCut;
	}

	if (state->pendingPostLoadRuntimeReset)
		shouldReset = true;
	// Loading screens animate geometry that camera-derived motion vectors cannot represent.
	if (loadingMenuOpen)
		shouldReset = true;
	// The main menu has camera-only motion, so synthesized motion vectors can preserve
	// temporal history there once the reprojection pass has run successfully.
	if (mainMenuOpen && !menuCameraMVsValid)
		shouldReset = true;

	if (shouldReset)
		RequestHistoryReset();

	previousHistoryScreenSize = screenSize;
	previousHistoryResolutionScale = resolutionScale;
	previousHistoryEngineRenderSize = engineRenderSize;
	previousHistoryFinalOutputSize = finalOutputSize;
	previousHistoryResolutionOwner = resolutionOwner;
	previousHistoryQualityMode = qualityMode;
	previousHistoryInWorld = inWorld;
	previousHistoryInMapMenu = inMapMenu;
	previousHistoryUpscaleMethod = a_upscaleMethod;
	previousHistoryFoveatedDispatch = foveatedDispatchEnabled;
	previousHistoryFoveatedCenterScale = foveatedCenterScale;
	previousHistoryFoveatedCenterHorizontalScale = foveatedCenterHorizontalScale;
	previousHistoryFoveatedCenterOffsets = foveatedCenterOffsets;
	previousHistoryPeripheryTAA = peripheryTAAEnabled;
	previousHistoryPeripheryTAAPathActive = peripheryTAAPathActive;
	previousHistoryPeripheryTAAOuterScale = peripheryTAAOuterScale;
	previousHistoryPeripheryTAACenterBlendFeather = peripheryTAACenterBlendFeather;
	previousHistoryFSRRuntimePathActive = fsrRuntimePathActive;
	previousHistoryFSRRuntimeFsr4Active = fsrRuntimeFsr4Active;
}

/**
 * @brief Retrieves the current frame time for frame generation.
 *
 * Returns the frame time from the D3D12 swap chain if frame generation is active; otherwise, returns 0.
 *
 * @return float The current frame time in seconds, or 0 if frame generation is inactive.
 */
float Upscaling::GetFrameGenerationFrameTime() const
{
	if (!IsFrameGenerationActive())
		return 0.0f;

	// Get the current frame time from D3D12 swapchain
	if (dx12SwapChain.swapChain) {
		// Get frame time from the D3D12 SwapChain
		return GetFrameTime();
	}

	return 0.0f;
}

// Unified interface methods
void Upscaling::LoadUpscalingSDKs()
{
	ApplyOpenCompositeUpscalingBlocker(true);
	const auto blocker = GetOpenCompositeUpscalingBlocker();
	if (blocker.active) {
		if (!openCompositeUpscalingBackendSkipLogged) {
			if (blocker.configPath.empty()) {
				logger::warn(
					"[Upscaling] Skipping CSX Streamline/FidelityFX backend initialization because Open Composite has {}=true.",
					blocker.settingName);
			} else {
				logger::warn(
					"[Upscaling] Skipping CSX Streamline/FidelityFX backend initialization because Open Composite has {}=true in {}.",
					blocker.settingName,
					blocker.configPath);
			}
			openCompositeUpscalingBackendSkipLogged = true;
		}
		return;
	}
	if (IsRenderDocUpscalingBlocked(true)) {
		if (!renderDocUpscalingBackendSkipLogged) {
			logger::warn(
				"[Upscaling] Skipping CSX Streamline/FidelityFX backend initialization because {}.",
				GetRenderDocUpscalingBlockReason());
			renderDocUpscalingBackendSkipLogged = true;
		}
		return;
	}

	// Initialize upscaling SDK components during plugin startup
	// This ensures all SDKs are available before any D3D device creation
	streamline.LoadInterposer();
	fidelityFX.LoadFFX();
	if (streamline.featureCheckComplete)
		CompleteDelayedVRPerfModeBootLatchForDLSSAvailability(*this, "Streamline DLSS availability resolved after deferred VR boot latch");
}

